const FARM_METHOD_CATS = ['prop', 'combo', 'soil', 'water', 'modern'];

const FARM_METHODS = [
/* ======================= Plants & grafting ======================= */
{ id: 'graft', cat: 'prop', icon: '🌳',
  k: ['graft', 'grafting', 'scion', 'rootstock', 'ग्राफ्टिंग', 'ग्राफ्ट', 'कलम', 'कलमी', 'सायन', 'रूटस्टॉक', 'टहनी', 'जोड़ना', 'जोड़कर', 'कलम करणे', 'खुंट', 'डोळकाडी', 'అంటు', 'అంటుకట్టడం', 'గ్రాఫ్టింగ్', 'ஒட்டு', 'ஒட்டுக்கட்டுதல்', 'கிராஃப்டிங்'],
  en: { t: 'Grafting', s: 'Join a good variety onto a strong root', how: 'A branch of a good variety (scion) is joined onto a young plant with strong roots (rootstock). Cut both cleanly with a sharp knife, fit the cut faces together so the green layers under the bark touch, and tie tightly with a plastic strip. The new tree gives fruit like the good variety and starts fruiting earlier than a seedling tree. Used for mango, guava, citrus and many other fruits; in most places a humid season like the monsoon works best.' },
  hi: { t: 'ग्राफ्टिंग (कलम बाँधना)', s: 'अच्छी किस्म को मज़बूत जड़ पर जोड़ना', how: 'अच्छी किस्म के पौधे की टहनी (सायन) को मज़बूत जड़ वाले छोटे पौधे (रूटस्टॉक) पर जोड़ा जाता है। दोनों को तेज़ साफ़ चाकू से काटें, कटे हिस्से ऐसे मिलाएँ कि छाल के नीचे की हरी परत आपस में छुए, और प्लास्टिक की पट्टी से कसकर बाँध दें। नया पेड़ अच्छी किस्म जैसे ही फल देता है और बीज वाले पौधे से जल्दी फल देने लगता है। आम, अमरूद, नींबू वर्गीय और कई फलों में इसका उपयोग होता है; ज़्यादातर जगहों पर बरसात का नम मौसम सबसे अच्छा रहता है।' },
  mr: { t: 'कलम करणे (ग्राफ्टिंग)', s: 'चांगली जात मजबूत खुंटावर जोडणे', how: 'चांगल्या जातीच्या झाडाची फांदी (डोळकाडी) मजबूत मुळे असलेल्या लहान रोपावर (खुंट) जोडली जाते. दोन्ही धारदार स्वच्छ चाकूने कापा, कापलेले भाग असे जुळवा की सालीखालचा हिरवा थर एकमेकांना लागेल, आणि प्लास्टिकच्या पट्टीने घट्ट बांधा. नवे झाड चांगल्या जातीसारखीच फळे देते आणि बियांपासूनच्या रोपापेक्षा लवकर फळावर येते. आंबा, पेरू, लिंबूवर्गीय आणि अनेक फळांसाठी वापरतात; बहुतेक ठिकाणी पावसाळ्याचे दमट हवामान उत्तम असते.' },
  te: { t: 'అంటుకట్టడం (గ్రాఫ్టింగ్)', s: 'మంచి రకాన్ని బలమైన వేరుపై కలపడం', how: 'మంచి రకం మొక్క కొమ్మను (సయాన్) బలమైన వేర్లు ఉన్న చిన్న మొక్కపై (రూట్‌స్టాక్) కలుపుతారు. రెండింటినీ పదునైన శుభ్రమైన కత్తితో కోసి, బెరడు కింది పచ్చని పొరలు ఒకదానికొకటి తగిలేలా కలిపి, ప్లాస్టిక్ పట్టీతో గట్టిగా కట్టండి. కొత్త చెట్టు మంచి రకం లాంటి పండ్లనే ఇస్తుంది, విత్తనం నుంచి పెరిగిన చెట్టు కంటే త్వరగా కాపుకు వస్తుంది. మామిడి, జామ, నిమ్మజాతి వంటి చాలా పండ్లలో వాడతారు; చాలా ప్రాంతాల్లో వర్షాకాలపు తేమ వాతావరణం అనుకూలం.' },
  ta: { t: 'ஒட்டுக்கட்டுதல் (கிராஃப்டிங்)', s: 'நல்ல ரகத்தை வலுவான வேர்ச்செடியில் இணைத்தல்', how: 'நல்ல ரகச் செடியின் கிளையை (ஒட்டுக்கிளை) வலுவான வேர் உள்ள இளம் செடியில் (வேர்ச்செடி) இணைக்கிறார்கள். இரண்டையும் கூர்மையான சுத்தமான கத்தியால் வெட்டி, பட்டைக்குக் கீழுள்ள பச்சை அடுக்குகள் ஒன்றையொன்று தொடும்படி பொருத்தி, பிளாஸ்டிக் பட்டையால் இறுக்கமாகக் கட்டுங்கள். புதிய மரம் நல்ல ரகத்தைப் போன்றே காய்க்கும்; விதைச் செடியை விட விரைவில் காய்க்கத் தொடங்கும். மா, கொய்யா, எலுமிச்சை வகைகள் உள்ளிட்ட பல பழங்களில் பயன்படுகிறது; பெரும்பாலான இடங்களில் மழைக்கால ஈரப்பதமான பருவம் ஏற்றது.' } },

{ id: 'veggraft', cat: 'prop', icon: '🍉',
  k: ['vegetable', 'vegetables', 'watermelon', 'pumpkin', 'bottle gourd', 'तरबूज़', 'कद्दू', 'लौकी', 'खरबूजा', 'जोड़ना', 'जोड़कर', 'जोड़', 'सब्ज़ी', 'सब्ज़ियों', 'कलिंगड', 'भोपळा', 'दुधी', 'भाजीपाला', 'పుచ్చ', 'పుచ్చకాయ', 'గుమ్మడి', 'సొర', 'కూరగాయ', 'కూరగాయల్లో', 'தர்பூசணி', 'பூசணி', 'சுரை', 'காய்கறி', 'காய்கறிகளில்'],
  en: { t: 'Vegetable grafting', s: 'Watermelon on a pumpkin or bottle gourd root', how: 'Seedlings of watermelon, muskmelon or cucumber are joined onto roots of bottle gourd or pumpkin, and tomato or brinjal onto a hardy wild brinjal root. The strong root resists many soil diseases like wilt and copes better with too much or too little water, so plants stay healthy and give more. After grafting, keep seedlings for a few days in a shaded, humid place so the joint heals; ready grafted seedlings can also be bought from some nurseries.' },
  hi: { t: 'सब्ज़ियों में ग्राफ्टिंग', s: 'कद्दू या लौकी की जड़ पर तरबूज़', how: 'तरबूज़, खरबूज़ा या खीरे के पौधों को लौकी या कद्दू की जड़ पर, और टमाटर या बैंगन को मज़बूत जंगली बैंगन की जड़ पर जोड़ा जाता है। मज़बूत जड़ उकठा (विल्ट) जैसे मिट्टी के कई रोगों से बचाती है और पानी की कमी या ज़्यादती को बेहतर सहती है, इसलिए पौधे स्वस्थ रहते हैं और ज़्यादा फल देते हैं। ग्राफ्टिंग के बाद पौधों को कुछ दिन छाया और नमी वाली जगह में रखें ताकि जोड़ भर जाए; ऐसे तैयार पौधे कुछ नर्सरियों से खरीदे भी जा सकते हैं।' },
  mr: { t: 'भाजीपाल्यात कलम', s: 'भोपळा किंवा दुधी भोपळ्याच्या मुळावर कलिंगड', how: 'कलिंगड, खरबूज किंवा काकडीची रोपे दुधी भोपळा किंवा भोपळ्याच्या मुळावर, आणि टोमॅटो किंवा वांगी मजबूत रानवांग्याच्या मुळावर जोडली जातात. मजबूत मुळे मर (विल्ट) सारख्या जमिनीतील अनेक रोगांपासून वाचवतात आणि पाण्याची कमतरता किंवा जास्ती चांगली सहन करतात, त्यामुळे झाडे निरोगी राहून जास्त उत्पादन देतात. कलम केल्यानंतर रोपे काही दिवस सावलीत आणि दमट जागी ठेवा म्हणजे जोड भरून येईल; अशी तयार रोपे काही रोपवाटिकांमध्ये विकतही मिळतात.' },
  te: { t: 'కూరగాయల్లో అంటుకట్టడం', s: 'గుమ్మడి లేదా సొర వేరుపై పుచ్చ', how: 'పుచ్చ, కర్బూజ లేదా దోస మొక్కలను సొర లేదా గుమ్మడి వేరుపై, టమాటా లేదా వంకాయను బలమైన అడవి వంగ వేరుపై కలుపుతారు. బలమైన వేరు ఎండు తెగులు (విల్ట్) వంటి నేల తెగుళ్ల నుంచి కాపాడుతుంది, నీరు తక్కువైనా ఎక్కువైనా బాగా తట్టుకుంటుంది, దాంతో మొక్కలు ఆరోగ్యంగా ఉండి ఎక్కువ దిగుబడి ఇస్తాయి. అంటుకట్టిన తర్వాత అతుకు అతుక్కునే వరకు కొన్ని రోజులు నీడ, తేమ ఉన్న చోట ఉంచండి; ఇలా తయారైన మొక్కలను కొన్ని నర్సరీల్లో కొనుక్కోవచ్చు.' },
  ta: { t: 'காய்கறிகளில் ஒட்டுக்கட்டுதல்', s: 'பூசணி அல்லது சுரை வேரில் தர்பூசணி', how: 'தர்பூசணி, முலாம்பழம் அல்லது வெள்ளரிச் செடிகளைச் சுரை அல்லது பூசணி வேரிலும், தக்காளி அல்லது கத்தரியை வலுவான காட்டுக் கத்தரி வேரிலும் இணைக்கிறார்கள். வலுவான வேர் வாடல் நோய் போன்ற பல மண்வழி நோய்களிலிருந்து காக்கும்; நீர் குறைந்தாலும் அதிகமானாலும் நன்றாகத் தாங்கும்; இதனால் செடிகள் ஆரோக்கியமாக இருந்து அதிக மகசூல் தரும். ஒட்டுக்கட்டிய பிறகு இணைப்பு ஒன்றுசேரும் வரை சில நாட்கள் நிழலும் ஈரப்பதமும் உள்ள இடத்தில் வையுங்கள்; இப்படித் தயாரான நாற்றுகளைச் சில நாற்றுப் பண்ணைகளில் வாங்கலாம்.' } },

{ id: 'budding', cat: 'prop', icon: '🌿',
  k: ['budding', 'bud', 't budding', 'बडिंग', 'कलिका', 'आँख', 'डोळा', 'डोळा भरणे', 'మొగ్గ', 'బడ్డింగ్', 'மொட்டு', 'பட்டிங்'],
  en: { t: 'Budding', s: 'Join a single bud instead of a branch', how: 'Instead of a whole branch, just one bud with a little bark is taken from a good variety and fitted into a cut in the rootstock’s bark (for example a T-shaped cut), then tied. It needs less plant material than grafting. Commonly used for citrus, ber and roses.' },
  hi: { t: 'बडिंग (कलिका लगाना)', s: 'टहनी की जगह सिर्फ़ एक आँख जोड़ना', how: 'पूरी टहनी की जगह अच्छी किस्म से सिर्फ़ एक आँख (कली) थोड़ी छाल के साथ ली जाती है और रूटस्टॉक की छाल में चीरा लगाकर (जैसे T आकार का) उसमें फँसाकर बाँध दी जाती है। इसमें ग्राफ्टिंग से कम पौध सामग्री लगती है। नींबू वर्गीय फलों, बेर और गुलाब में यह आम है।' },
  mr: { t: 'डोळा भरणे (बडिंग)', s: 'फांदीऐवजी फक्त एक डोळा जोडणे', how: 'संपूर्ण फांदीऐवजी चांगल्या जातीचा फक्त एक डोळा थोड्या सालीसह घेतला जातो आणि खुंटाच्या सालीला छेद देऊन (उदा. T आकाराचा) त्यात बसवून बांधला जातो. यासाठी कलमापेक्षा कमी काडी लागते. लिंबूवर्गीय फळे, बोर आणि गुलाबात हे सामान्य आहे.' },
  te: { t: 'మొగ్గ అంటు (బడ్డింగ్)', s: 'కొమ్మకు బదులు ఒక మొగ్గను కలపడం', how: 'మొత్తం కొమ్మకు బదులు మంచి రకం నుంచి కొంచెం బెరడుతో ఒక్క మొగ్గను తీసి, రూట్‌స్టాక్ బెరడుపై గాటు పెట్టి (ఉదా. T ఆకారంలో) అందులో అమర్చి కడతారు. దీనికి అంటుకట్టడం కంటే తక్కువ మొక్క భాగం సరిపోతుంది. నిమ్మజాతి, రేగు, గులాబీల్లో ఇది సాధారణం.' },
  ta: { t: 'மொட்டுக் கட்டுதல் (பட்டிங்)', s: 'கிளைக்குப் பதில் ஒரு மொட்டை இணைத்தல்', how: 'முழுக் கிளைக்குப் பதிலாக நல்ல ரகத்திலிருந்து சிறிது பட்டையுடன் ஒரே ஒரு மொட்டை எடுத்து, வேர்ச்செடியின் பட்டையில் கீறல் (எ.கா. T வடிவம்) போட்டு அதில் பொருத்திக் கட்டுகிறார்கள். இதற்கு ஒட்டுக்கட்டுதலை விடக் குறைந்த செடிப் பகுதி போதும். எலுமிச்சை வகைகள், இலந்தை, ரோஜாவில் இது பொதுவானது.' } },

{ id: 'layering', cat: 'prop', icon: '🍃',
  k: ['layering', 'air layering', 'gootee', 'गूटी', 'गुटी', 'लेयरिंग', 'दाब कलम', 'गुटी कलम', 'గూటీ', 'లేయరింగ్', 'பதியம்'],
  en: { t: 'Air layering (gootee)', s: 'Grow roots on a branch while it is still on the tree', how: 'Remove a ring of bark about 2–3 cm wide from a healthy branch, cover the spot with moist moss or soil, and wrap it tightly in plastic. Roots form in a few weeks; then cut the branch below the roots and plant it. The new plant is exactly like the mother tree. Used for litchi, guava, pomegranate and lemon.' },
  hi: { t: 'गूटी बाँधना (एयर लेयरिंग)', s: 'पेड़ पर लगी टहनी पर ही जड़ें उगाना', how: 'स्वस्थ टहनी से 2–3 सेंटीमीटर चौड़ी छाल का छल्ला हटाएँ, उस जगह को गीली काई या मिट्टी से ढकें और प्लास्टिक से कसकर लपेट दें। कुछ हफ़्तों में जड़ें निकल आती हैं, फिर जड़ों के नीचे से टहनी काटकर लगा दें। नया पौधा बिल्कुल माँ पेड़ जैसा होता है। लीची, अमरूद, अनार और नींबू में इसका उपयोग होता है।' },
  mr: { t: 'गुटी कलम (एअर लेयरिंग)', s: 'झाडावरील फांदीवरच मुळे फुटवणे', how: 'निरोगी फांदीची 2–3 सेंटीमीटर रुंद साल गोलाकार काढा, त्या जागी ओले शेवाळ किंवा माती लावा आणि प्लास्टिकने घट्ट गुंडाळा. काही आठवड्यांत मुळे फुटतात, मग मुळांच्या खालून फांदी कापून लावा. नवे झाड अगदी मूळ झाडासारखे असते. लिची, पेरू, डाळिंब आणि लिंबूसाठी वापरतात.' },
  te: { t: 'గూటీ కట్టడం (ఎయిర్ లేయరింగ్)', s: 'చెట్టుపై ఉన్న కొమ్మకే వేర్లు రప్పించడం', how: 'ఆరోగ్యకరమైన కొమ్మ నుంచి 2–3 సెంటీమీటర్ల వెడల్పు బెరడు ఉంగరంలా తీసి, ఆ చోట తడి నాచు లేదా మట్టి పెట్టి, ప్లాస్టిక్‌తో గట్టిగా చుట్టండి. కొన్ని వారాల్లో వేర్లు వస్తాయి, అప్పుడు వేర్ల కింద కొమ్మను కోసి నాటండి. కొత్త మొక్క అచ్చం తల్లి చెట్టు లాగే ఉంటుంది. లిచీ, జామ, దానిమ్మ, నిమ్మలో వాడతారు.' },
  ta: { t: 'பதியம் போடுதல் (காற்றுப் பதியம்)', s: 'மரத்திலுள்ள கிளையிலேயே வேர் வரவைத்தல்', how: 'ஆரோக்கியமான கிளையில் 2–3 சென்டிமீட்டர் அகலத்துக்குப் பட்டையை வளையமாக நீக்கி, அந்த இடத்தை ஈரமான பாசி அல்லது மண்ணால் மூடி, பிளாஸ்டிக்கால் இறுக்கமாகச் சுற்றுங்கள். சில வாரங்களில் வேர்கள் வரும்; பிறகு வேருக்குக் கீழே கிளையை வெட்டி நடுங்கள். புதிய செடி தாய் மரத்தைப் போலவே இருக்கும். லிச்சி, கொய்யா, மாதுளை, எலுமிச்சையில் பயன்படுகிறது.' } },

{ id: 'cuttings', cat: 'prop', icon: '✂️',
  k: ['cutting', 'cuttings', 'sett', 'setts', 'कटिंग', 'कलम', 'गुल्ली', 'छाट कलम', 'कांडी', 'टिपरी', 'కొమ్మ ముక్క', 'ముచ్చెలు', 'కటింగ్', 'கரணை', 'தண்டுத் துண்டு'],
  en: { t: 'Plants from cuttings', s: 'Grow new plants from pieces of stem', how: 'Pieces of healthy stem, usually as thick as a pencil with 3–4 buds, are planted in moist soil or a nursery bag; dipping the lower end in rooting powder helps. Each piece grows into a plant like the mother plant. Grapes, pomegranate, drumstick (moringa) and roses are grown this way, and sugarcane is planted from stem pieces called setts.' },
  hi: { t: 'कटिंग से पौधे', s: 'तने के टुकड़ों से नए पौधे', how: 'स्वस्थ तने के टुकड़े, आमतौर पर पेंसिल जितने मोटे और 3–4 आँखों वाले, नम मिट्टी या नर्सरी की थैली में लगाए जाते हैं; नीचे का सिरा जड़ बढ़ाने वाले पाउडर में डुबोने से मदद मिलती है। हर टुकड़ा माँ पौधे जैसा पौधा बनता है। अंगूर, अनार, सहजन और गुलाब ऐसे उगाए जाते हैं, और गन्ना भी तने के टुकड़ों (गुल्ली या सेट) से बोया जाता है।' },
  mr: { t: 'छाट कलम (कटिंग)', s: 'खोडाच्या तुकड्यांपासून नवी रोपे', how: 'निरोगी खोडाचे तुकडे, साधारण पेन्सिलइतके जाड आणि 3–4 डोळे असलेले, ओलसर मातीत किंवा रोपवाटिकेच्या पिशवीत लावले जातात; खालचे टोक मुळे फुटवणाऱ्या पावडरमध्ये बुडवल्यास मदत होते. प्रत्येक तुकडा मूळ झाडासारखे रोप बनतो. द्राक्षे, डाळिंब, शेवगा आणि गुलाब असे लावतात, आणि ऊसही कांड्यांपासून (टिपरी) लावला जातो.' },
  te: { t: 'కొమ్మ ముక్కలతో మొక్కలు', s: 'కాండం ముక్కల నుంచి కొత్త మొక్కలు', how: 'ఆరోగ్యకరమైన కాండం ముక్కలను, సాధారణంగా పెన్సిల్ అంత లావుగా 3–4 కణుపులతో, తడి మట్టిలో లేదా నర్సరీ సంచిలో నాటుతారు; కింది చివరను వేర్లు వచ్చే పొడిలో ముంచితే మేలు. ప్రతి ముక్క తల్లి మొక్క లాంటి మొక్కగా పెరుగుతుంది. ద్రాక్ష, దానిమ్మ, మునగ, గులాబీ ఇలా పెంచుతారు, చెరకును కూడా కాండం ముక్కలతో (ముచ్చెలు) నాటుతారు.' },
  ta: { t: 'தண்டுத் துண்டுகளால் நாற்று', s: 'தண்டுத் துண்டுகளிலிருந்து புதிய செடிகள்', how: 'ஆரோக்கியமான தண்டுத் துண்டுகளை, பொதுவாகப் பென்சில் அளவு தடிமனும் 3–4 கணுக்களும் உள்ளவற்றை, ஈர மண்ணில் அல்லது நாற்றுப் பையில் நடுகிறார்கள்; கீழ் முனையை வேர் ஊக்கப் பொடியில் நனைத்தால் உதவும். ஒவ்வொரு துண்டும் தாய்ச் செடியைப் போன்ற செடியாக வளரும். திராட்சை, மாதுளை, முருங்கை, ரோஜா இப்படி வளர்க்கப்படுகின்றன; கரும்பும் தண்டுக் கரணைகளால் நடப்படுகிறது.' } },

{ id: 'tissue', cat: 'prop', icon: '🧫',
  k: ['tissue culture', 'tissue', 'lab plants', 'टिशू कल्चर', 'टिशू', 'टिश्यू', 'ऊती संवर्धन', 'लैब', 'టిష్యూ', 'టిష్యూ కల్చర్', 'திசு வளர்ப்பு', 'திசு'],
  en: { t: 'Tissue culture plants', s: 'Disease-free plants grown in a lab', how: 'Thousands of identical plants are grown in a laboratory from a tiny piece of a healthy mother plant. They are free from many diseases, grow evenly and are ready at the same time, which makes harvesting and selling easier. Common for banana, sugarcane and potato; buy only from certified labs or government-approved nurseries.' },
  hi: { t: 'टिशू कल्चर पौधे', s: 'लैब में तैयार रोग-मुक्त पौधे', how: 'स्वस्थ माँ पौधे के छोटे से हिस्से से लैब में हज़ारों एक जैसे पौधे तैयार किए जाते हैं। ये कई रोगों से मुक्त होते हैं, एक समान बढ़ते हैं और एक साथ तैयार होते हैं, जिससे कटाई और बिक्री आसान होती है। केला, गन्ना और आलू में आम हैं; पौधे सिर्फ़ प्रमाणित लैब या सरकारी मान्यता वाली नर्सरी से खरीदें।' },
  mr: { t: 'ऊती संवर्धन (टिश्यू कल्चर) रोपे', s: 'प्रयोगशाळेत तयार रोगमुक्त रोपे', how: 'निरोगी मातृ झाडाच्या लहानशा भागापासून प्रयोगशाळेत हजारो एकसारखी रोपे तयार केली जातात. ती अनेक रोगांपासून मुक्त असतात, एकसारखी वाढतात आणि एकाच वेळी तयार होतात, त्यामुळे काढणी आणि विक्री सोपी होते. केळी, ऊस आणि बटाट्यात सामान्य आहेत; रोपे फक्त प्रमाणित प्रयोगशाळा किंवा शासनमान्य रोपवाटिकेतूनच घ्या.' },
  te: { t: 'టిష్యూ కల్చర్ మొక్కలు', s: 'ల్యాబ్‌లో తయారైన తెగులు లేని మొక్కలు', how: 'ఆరోగ్యకరమైన తల్లి మొక్క చిన్న భాగం నుంచి ల్యాబ్‌లో వేలాది ఒకేలాంటి మొక్కలు తయారు చేస్తారు. ఇవి చాలా తెగుళ్ల నుంచి విముక్తంగా ఉంటాయి, సమానంగా పెరుగుతాయి, ఒకేసారి కోతకు వస్తాయి, దాంతో కోత, అమ్మకం సులభం. అరటి, చెరకు, బంగాళాదుంపలో సాధారణం; ధృవీకరించిన ల్యాబ్ లేదా ప్రభుత్వ గుర్తింపు ఉన్న నర్సరీ నుంచే కొనండి.' },
  ta: { t: 'திசு வளர்ப்பு நாற்றுகள்', s: 'ஆய்வகத்தில் தயாரான நோயற்ற நாற்றுகள்', how: 'ஆரோக்கியமான தாய்ச் செடியின் சிறு பகுதியிலிருந்து ஆய்வகத்தில் ஆயிரக்கணக்கான ஒரே மாதிரியான நாற்றுகள் தயாரிக்கப்படுகின்றன. இவை பல நோய்களிலிருந்து விடுபட்டவை, சீராக வளர்ந்து ஒரே நேரத்தில் அறுவடைக்கு வரும்; இதனால் அறுவடையும் விற்பனையும் எளிது. வாழை, கரும்பு, உருளைக்கிழங்கில் பொதுவானது; சான்று பெற்ற ஆய்வகம் அல்லது அரசு அங்கீகாரம் உள்ள நாற்றுப் பண்ணையில் மட்டுமே வாங்குங்கள்.' } },

{ id: 'protray', cat: 'prop', icon: '🌱',
  k: ['तैयार', 'पौध तैयार', 'raising', 'pro tray', 'protray', 'nursery', 'seedling', 'seedlings', 'cocopeat', 'प्रो ट्रे', 'प्रोट्रे', 'नर्सरी', 'पौध', 'कोकोपीट', 'रोपवाटिका', 'रोपे', 'నర్సరీ', 'నారు', 'ప్రో ట్రే', 'நாற்றங்கால்', 'குழித்தட்டு', 'நாற்று'],
  en: { t: 'Pro-tray nursery', s: 'Healthy vegetable seedlings in trays', how: 'Vegetable seeds like tomato, chilli, brinjal and cauliflower are sown one per cell in plastic trays filled with a cocopeat mixture and kept under a net or shade. Seedlings grow evenly with roots held in a ball of soil, so fewer die after transplanting and less seed is wasted. Many farmers also buy such seedlings from local nurseries.' },
  hi: { t: 'प्रो-ट्रे नर्सरी', s: 'ट्रे में स्वस्थ सब्ज़ी पौध', how: 'टमाटर, मिर्च, बैंगन, गोभी जैसी सब्ज़ियों के बीज कोकोपीट मिश्रण से भरी प्लास्टिक ट्रे के हर खाने में एक-एक बोए जाते हैं और जाली या छाया में रखे जाते हैं। पौध एक समान बढ़ती है और जड़ें मिट्टी के गोले के साथ रहती हैं, इसलिए रोपाई के बाद कम पौधे मरते हैं और बीज भी कम बर्बाद होता है। कई किसान ऐसी पौध पास की नर्सरी से खरीदते भी हैं।' },
  mr: { t: 'प्रो-ट्रे रोपवाटिका', s: 'ट्रेमध्ये निरोगी भाजीपाला रोपे', how: 'टोमॅटो, मिरची, वांगी, फुलकोबी अशा भाज्यांचे बी कोकोपीट मिश्रणाने भरलेल्या प्लास्टिक ट्रेच्या प्रत्येक कप्प्यात एक-एक पेरले जाते आणि जाळी किंवा सावलीत ठेवले जाते. रोपे एकसारखी वाढतात आणि मुळे मातीच्या गोळ्यासह राहतात, त्यामुळे लागवडीनंतर कमी रोपे मरतात आणि बियाणेही कमी वाया जाते. अनेक शेतकरी अशी रोपे जवळच्या रोपवाटिकेतून विकतही घेतात.' },
  te: { t: 'ప్రో-ట్రే నర్సరీ', s: 'ట్రేలలో ఆరోగ్యకరమైన కూరగాయ నారు', how: 'టమాటా, మిరప, వంకాయ, కాలీఫ్లవర్ వంటి కూరగాయ విత్తనాలను కోకోపీట్ మిశ్రమంతో నింపిన ప్లాస్టిక్ ట్రేల ప్రతి గుంతలో ఒక్కొక్కటి విత్తి, వల లేదా నీడ కింద ఉంచుతారు. నారు సమానంగా పెరుగుతుంది, వేర్లు మట్టి ముద్దతో ఉంటాయి, అందుకే నాటిన తర్వాత తక్కువ మొక్కలు చనిపోతాయి, విత్తనం వృథా తగ్గుతుంది. చాలా మంది రైతులు ఇలాంటి నారును దగ్గరి నర్సరీల్లో కొంటారు కూడా.' },
  ta: { t: 'குழித்தட்டு நாற்றங்கால்', s: 'தட்டுகளில் ஆரோக்கியமான காய்கறி நாற்று', how: 'தக்காளி, மிளகாய், கத்தரி, காலிஃபிளவர் போன்ற காய்கறி விதைகளைத் தென்னை நார்க்கழிவுக் கலவை நிரப்பிய பிளாஸ்டிக் குழித்தட்டின் ஒவ்வொரு குழியிலும் ஒன்றாக விதைத்து, வலை அல்லது நிழலில் வைக்கிறார்கள். நாற்றுகள் சீராக வளரும், வேர்கள் மண் உருண்டையுடன் இருக்கும்; இதனால் நடவுக்குப் பின் குறைவான நாற்றுகளே இறக்கும், விதையும் குறைவாக வீணாகும். பல விவசாயிகள் இத்தகைய நாற்றுகளை அருகிலுள்ள நாற்றுப் பண்ணைகளில் வாங்குகிறார்கள்.' } },

/* ======================= Growing crops together ======================= */
{ id: 'intercrop', cat: 'combo', icon: '🌽',
  k: ['space', 'same land', 'जगह', 'जागा', 'స్థలం', 'இடம்', 'intercrop', 'intercropping', 'mixed cropping', 'companion', 'two crops', 'together', 'अंतर फसल', 'अंतरफसल', 'सहफसली', 'मिश्रित खेती', 'एक साथ', 'दो फसल', 'दो फसलें', 'साथ में', 'आंतरपीक', 'मिश्र पीक', 'अंतर', 'అంతర పంట', 'అంతర పంటలు', 'మిశ్రమ పంట', 'కలిపి', 'ஊடுபயிர்', 'கலப்புப் பயிர்', 'சேர்த்து'],
  en: { t: 'Intercropping', s: 'Two crops in the same field at the same time', how: 'Rows of a main crop and a second crop are grown together, for example arhar with soybean or urad, sugarcane with onion or potato in its early months, maize with cowpea, or cotton with moong. Pair a tall crop with a short one, deep roots with shallow roots, or a long-duration crop with a short one, so they do not compete much. You get extra harvest from the same land, if one crop fails the other still earns, and pulses also add nitrogen to the soil.' },
  hi: { t: 'अंतर-फसल (सहफसली खेती)', s: 'एक खेत में एक साथ दो फसलें', how: 'मुख्य फसल और दूसरी फसल की कतारें साथ-साथ उगाई जाती हैं, जैसे अरहर के साथ सोयाबीन या उड़द, गन्ने के शुरुआती महीनों में प्याज़ या आलू, मक्का के साथ लोबिया, या कपास के साथ मूँग। लंबी फसल के साथ छोटी, गहरी जड़ वाली के साथ उथली जड़ वाली, या लंबी अवधि वाली के साथ कम अवधि वाली फसल चुनें ताकि दोनों में ज़्यादा होड़ न हो। एक ही ज़मीन से अतिरिक्त उपज मिलती है, एक फसल खराब हो तो दूसरी से कमाई होती है, और दालें मिट्टी में नाइट्रोजन भी बढ़ाती हैं।' },
  mr: { t: 'आंतरपीक', s: 'एका शेतात एकाच वेळी दोन पिके', how: 'मुख्य पीक आणि दुसऱ्या पिकाच्या ओळी एकत्र घेतल्या जातात, जसे तुरीसोबत सोयाबीन किंवा उडीद, उसाच्या सुरुवातीच्या महिन्यांत कांदा किंवा बटाटा, मक्यासोबत चवळी, किंवा कापसासोबत मूग. उंच पिकासोबत बुटके, खोल मुळांच्या पिकासोबत उथळ मुळांचे, किंवा जास्त कालावधीच्या पिकासोबत कमी कालावधीचे पीक निवडा म्हणजे दोघांत फार स्पर्धा होत नाही. एकाच जमिनीतून जादा उत्पादन मिळते, एक पीक बुडाले तरी दुसऱ्यातून उत्पन्न मिळते, आणि कडधान्ये जमिनीत नत्रही वाढवतात.' },
  te: { t: 'అంతర పంటలు', s: 'ఒకే పొలంలో ఒకేసారి రెండు పంటలు', how: 'ప్రధాన పంట, రెండో పంట వరుసలను కలిపి పండిస్తారు, ఉదాహరణకు కందితో సోయాబీన్ లేదా మినుము, చెరకు మొదటి నెలల్లో ఉల్లి లేదా బంగాళాదుంప, మొక్కజొన్నతో అలసంద, పత్తితో పెసర. పొడవైన పంటతో పొట్టిది, లోతైన వేర్లతో పైపై వేర్లది, ఎక్కువ కాలం పంటతో తక్కువ కాలం పంటను జత చేయండి, అప్పుడు రెండూ పెద్దగా పోటీ పడవు. అదే భూమి నుంచి అదనపు దిగుబడి వస్తుంది, ఒక పంట పోయినా మరొకటి ఆదాయం ఇస్తుంది, పప్పు పంటలు నేలలో నత్రజనిని కూడా పెంచుతాయి.' },
  ta: { t: 'ஊடுபயிர்', s: 'ஒரே வயலில் ஒரே நேரத்தில் இரண்டு பயிர்கள்', how: 'முதன்மைப் பயிரும் இரண்டாம் பயிரும் வரிசைகளாகச் சேர்த்து வளர்க்கப்படுகின்றன; எ.கா. துவரையுடன் சோயாபீன் அல்லது உளுந்து, கரும்பின் தொடக்க மாதங்களில் வெங்காயம் அல்லது உருளைக்கிழங்கு, மக்காச்சோளத்துடன் தட்டைப்பயறு, பருத்தியுடன் பாசிப்பயறு. உயரமான பயிருடன் குட்டையானது, ஆழ வேர் பயிருடன் மேலோட்ட வேர் பயிர், நீண்ட காலப் பயிருடன் குறுகிய காலப் பயிர் என இணைத்தால் இரண்டுக்கும் அதிகப் போட்டி இருக்காது. அதே நிலத்தில் கூடுதல் மகசூல் கிடைக்கும்; ஒரு பயிர் தோற்றாலும் மற்றொன்று வருமானம் தரும்; பயறு வகைகள் மண்ணில் தழைச்சத்தையும் கூட்டும்.' } },

{ id: 'trapcrop', cat: 'combo', icon: '🌼',
  k: ['trap crop', 'border crop', 'companion planting', 'marigold', 'गेंदा', 'गेंदे', 'ट्रैप फसल', 'मेड़ फसल', 'सरसों', 'झेंडू', 'सापळा पीक', 'బంతి', 'ఎర పంట', 'గట్టు పంట', 'சாமந்தி', 'கவர்ச்சிப் பயிர்', 'வரப்புப் பயிர்'],
  en: { t: 'Trap and border crops', s: 'Plants that pull pests away from the main crop', how: 'Some plants attract pests so the main crop is spared. Marigold rows around or within tomato attract the fruit borer, and a few rows of mustard in cabbage attract the diamondback moth; pests gathered on these plants are easier to control. Tall border crops like maize or sorghum around a field can also block some flying pests. Ask your Krishi Vigyan Kendra which pairs suit your crop.' },
  hi: { t: 'ट्रैप फसल और मेड़ फसल', s: 'ऐसे पौधे जो कीटों को मुख्य फसल से दूर खींचें', how: 'कुछ पौधे कीटों को अपनी ओर खींचते हैं, जिससे मुख्य फसल बच जाती है। टमाटर के आसपास या बीच में गेंदे की कतारें फल छेदक को खींचती हैं, और पत्तागोभी में सरसों की कुछ कतारें डायमंड बैक मोथ को खींचती हैं; इन पौधों पर जमा कीटों को काबू करना आसान होता है। खेत के चारों ओर मक्का या ज्वार जैसी ऊँची मेड़ फसल कुछ उड़ने वाले कीटों को भी रोकती है। आपकी फसल के लिए कौन सी जोड़ी ठीक है, यह कृषि विज्ञान केंद्र से पूछें।' },
  mr: { t: 'सापळा पीक आणि कडेचे पीक', s: 'किडींना मुख्य पिकापासून दूर ओढणारी झाडे', how: 'काही झाडे किडींना आपल्याकडे ओढतात, त्यामुळे मुख्य पीक वाचते. टोमॅटोभोवती किंवा मध्ये झेंडूच्या ओळी फळ पोखरणाऱ्या अळीला ओढतात, आणि कोबीत मोहरीच्या काही ओळी चौकोनी ठिपक्यांच्या पतंगाला (डायमंड बॅक मॉथ) ओढतात; या झाडांवर जमलेल्या किडींचे नियंत्रण सोपे होते. शेताभोवती मका किंवा ज्वारीसारखे उंच कडेचे पीक काही उडणाऱ्या किडींनाही अडवते. आपल्या पिकासाठी कोणती जोडी योग्य आहे ते कृषी विज्ञान केंद्रात विचारा.' },
  te: { t: 'ఎర పంటలు, గట్టు పంటలు', s: 'పురుగులను ప్రధాన పంట నుంచి దూరంగా లాగే మొక్కలు', how: 'కొన్ని మొక్కలు పురుగులను తమ వైపు ఆకర్షిస్తాయి, దాంతో ప్రధాన పంట బతుకుతుంది. టమాటా చుట్టూ లేదా మధ్యలో బంతి వరుసలు కాయ తొలిచే పురుగును ఆకర్షిస్తాయి, క్యాబేజీలో కొన్ని ఆవాల వరుసలు డైమండ్ బ్యాక్ మాత్‌ను ఆకర్షిస్తాయి; ఈ మొక్కలపై చేరిన పురుగులను అదుపు చేయడం సులభం. పొలం చుట్టూ మొక్కజొన్న లేదా జొన్న వంటి పొడవైన గట్టు పంట కొన్ని ఎగిరే పురుగులను అడ్డుకుంటుంది. మీ పంటకు ఏ జత సరిపోతుందో కృషి విజ్ఞాన కేంద్రంలో అడగండి.' },
  ta: { t: 'கவர்ச்சிப் பயிர், வரப்புப் பயிர்', s: 'பூச்சிகளை முதன்மைப் பயிரிலிருந்து இழுக்கும் செடிகள்', how: 'சில செடிகள் பூச்சிகளைத் தம்மிடம் ஈர்க்கின்றன; இதனால் முதன்மைப் பயிர் தப்பும். தக்காளியைச் சுற்றியோ நடுவிலோ சாமந்தி வரிசைகள் காய்ப்புழுவை ஈர்க்கும்; முட்டைக்கோஸில் சில கடுகு வரிசைகள் வைரமுதுகு அந்துப்பூச்சியை ஈர்க்கும்; இந்தச் செடிகளில் கூடும் பூச்சிகளைக் கட்டுப்படுத்துவது எளிது. வயலைச் சுற்றி மக்காச்சோளம் அல்லது சோளம் போன்ற உயரமான வரப்புப் பயிர் சில பறக்கும் பூச்சிகளைத் தடுக்கும். உங்கள் பயிருக்கு எந்த இணை பொருந்தும் என்று வேளாண் அறிவியல் நிலையத்தில் கேளுங்கள்.' } },

{ id: 'multilayer', cat: 'combo', icon: '🌴',
  k: ['space', 'less land', 'small land', 'जगह', 'कम जगह', 'कम ज़मीन', 'जागा', 'कमी जागा', 'స్థలం', 'తక్కువ స్థలం', 'இடம்', 'குறைந்த இடம்', 'multilayer', 'multi layer', 'multi tier', 'multistorey', 'layers', 'मल्टीलेयर', 'बहुस्तरीय', 'बहुमंज़िला', 'परत', 'परतों', 'मचान', 'बहुस्तरीय शेती', 'थर', 'బహుళ అంతస్తుల', 'అంతస్తుల', 'పొరలు', 'பல அடுக்கு', 'அடுக்கு'],
  en: { t: 'Multilayer farming', s: 'Plants of different heights in one plot', how: 'Crops of different heights and root depths share the same land: for example ginger or turmeric under the soil, leafy vegetables on the ground, gourds climbing on a trellis above, and papaya or banana as the tallest layer. In coconut gardens, banana, pineapple or black pepper are grown under the palms. Sunlight, water and land are used fully, so income per acre goes up; plan spacing so lower crops still get enough light.' },
  hi: { t: 'बहुस्तरीय खेती (मल्टीलेयर)', s: 'एक खेत में अलग-अलग ऊँचाई के पौधे', how: 'अलग-अलग ऊँचाई और जड़ की गहराई वाली फसलें एक ही ज़मीन साझा करती हैं: जैसे मिट्टी के अंदर अदरक या हल्दी, ज़मीन पर पत्तेदार सब्ज़ी, ऊपर मचान पर बेल वाली सब्ज़ियाँ, और सबसे ऊँची परत में पपीता या केला। नारियल के बागों में पेड़ों के नीचे केला, अनानास या काली मिर्च उगाई जाती है। धूप, पानी और ज़मीन का पूरा उपयोग होता है, इसलिए प्रति एकड़ कमाई बढ़ती है; दूरी ऐसी रखें कि नीचे की फसलों को भी पूरी रोशनी मिले।' },
  mr: { t: 'बहुस्तरीय शेती', s: 'एका शेतात वेगवेगळ्या उंचीची झाडे', how: 'वेगवेगळी उंची आणि मुळांची खोली असलेली पिके एकच जमीन वाटून घेतात: जसे मातीत आले किंवा हळद, जमिनीवर पालेभाज्या, वर मांडवावर वेलवर्गीय भाज्या, आणि सर्वात उंच थरात पपई किंवा केळी. नारळाच्या बागेत झाडांखाली केळी, अननस किंवा मिरी घेतली जाते. सूर्यप्रकाश, पाणी आणि जमिनीचा पूर्ण वापर होतो, त्यामुळे एकरी उत्पन्न वाढते; खालच्या पिकांनाही पुरेसा प्रकाश मिळेल असे अंतर ठेवा.' },
  te: { t: 'బహుళ అంతస్తుల సాగు', s: 'ఒకే చోట వేర్వేరు ఎత్తుల మొక్కలు', how: 'వేర్వేరు ఎత్తు, వేరు లోతు ఉన్న పంటలు ఒకే భూమిని పంచుకుంటాయి: ఉదాహరణకు నేల లోపల అల్లం లేదా పసుపు, నేలపై ఆకుకూరలు, పైన పందిరిపై తీగ కూరగాయలు, అన్నిటికంటే ఎత్తులో బొప్పాయి లేదా అరటి. కొబ్బరి తోటల్లో చెట్ల కింద అరటి, అనాస లేదా మిరియాలు పండిస్తారు. ఎండ, నీరు, భూమి పూర్తిగా వాడుకలోకి వస్తాయి, అందుకే ఎకరానికి ఆదాయం పెరుగుతుంది; కింది పంటలకు కూడా తగినంత వెలుతురు అందేలా దూరం ఉంచండి.' },
  ta: { t: 'பல அடுக்கு சாகுபடி', s: 'ஒரே இடத்தில் வெவ்வேறு உயரச் செடிகள்', how: 'வெவ்வேறு உயரமும் வேர் ஆழமும் உள்ள பயிர்கள் ஒரே நிலத்தைப் பகிர்ந்துகொள்கின்றன: எ.கா. மண்ணுக்குள் இஞ்சி அல்லது மஞ்சள், தரையில் கீரை வகைகள், மேலே பந்தலில் கொடிக் காய்கறிகள், மிக உயரமான அடுக்கில் பப்பாளி அல்லது வாழை. தென்னந்தோப்புகளில் மரங்களுக்குக் கீழே வாழை, அன்னாசி அல்லது மிளகு வளர்க்கப்படுகிறது. வெயில், நீர், நிலம் முழுமையாகப் பயன்படுவதால் ஏக்கருக்கு வருமானம் கூடும்; கீழ்ப் பயிர்களுக்கும் போதுமான வெளிச்சம் கிடைக்கும்படி இடைவெளி விடுங்கள்.' } },

{ id: 'relay', cat: 'combo', icon: '🌾',
  k: ['relay', 'relay cropping', 'utera', 'paira', 'rice fallow', 'रिले', 'उतेरा', 'पैरा', 'खड़ी फसल', 'रिले पीक', 'उतेरा पीक', 'రిలే', 'ఉతేరా', 'వరి మాగాణి', 'ரிலே', 'நெல் தரிசு', 'தொடர் பயிர்'],
  en: { t: 'Relay cropping (utera)', s: 'Sow the next crop before harvesting this one', how: 'Seeds of the next crop are sown into the standing crop a few days or weeks before its harvest, for example lentil, lathyrus or linseed broadcast into standing paddy in eastern and central India, or urad and moong sown into paddy just before harvest in the Cauvery delta and coastal Andhra. The new crop uses the leftover soil moisture and gets extra growing time, so a second crop is possible even without irrigation.' },
  hi: { t: 'रिले फसल (उतेरा / पैरा)', s: 'एक फसल कटने से पहले अगली बो देना', how: 'खड़ी फसल की कटाई से कुछ दिन या हफ़्ते पहले उसी में अगली फसल के बीज बो दिए जाते हैं, जैसे पूर्वी और मध्य भारत में खड़े धान में मसूर, खेसारी या अलसी छिड़कना, या कावेरी डेल्टा और तटीय आंध्र में कटाई से ठीक पहले धान में उड़द और मूँग बोना। नई फसल बची हुई नमी का उपयोग करती है और उसे बढ़ने का अधिक समय मिलता है, इसलिए बिना सिंचाई के भी दूसरी फसल ली जा सकती है।' },
  mr: { t: 'रिले पीक (उतेरा)', s: 'एक पीक काढण्यापूर्वी पुढचे पेरणे', how: 'उभ्या पिकाच्या काढणीच्या काही दिवस किंवा आठवडे आधी त्यातच पुढच्या पिकाचे बी पेरले जाते, जसे पूर्व आणि मध्य भारतात उभ्या भातात मसूर, लाख किंवा जवस फेकून पेरणे, किंवा कावेरी त्रिभुज प्रदेश आणि किनारी आंध्रात काढणीच्या थोडे आधी भातात उडीद आणि मूग पेरणे. नवे पीक उरलेल्या ओलाव्याचा वापर करते आणि त्याला वाढीसाठी जास्त वेळ मिळतो, त्यामुळे सिंचनाशिवायही दुसरे पीक घेता येते.' },
  te: { t: 'రిలే పంట (ఉతేరా)', s: 'ఈ పంట కోయక ముందే తదుపరి పంట విత్తడం', how: 'నిలబడి ఉన్న పంట కోతకు కొన్ని రోజులు లేదా వారాల ముందే అందులో తదుపరి పంట విత్తనాలు చల్లుతారు, ఉదాహరణకు తూర్పు, మధ్య భారతదేశంలో నిలబడిన వరిలో మసూర్, లాతిరస్ లేదా అవిసె చల్లడం, లేదా కావేరి డెల్టా, కోస్తా ఆంధ్రలో కోతకు ముందు వరిలో మినుము, పెసర చల్లడం. కొత్త పంట మిగిలిన నేల తేమను వాడుకుంటుంది, పెరగడానికి ఎక్కువ సమయం దొరుకుతుంది, అందుకే సాగునీరు లేకపోయినా రెండో పంట సాధ్యం.' },
  ta: { t: 'தொடர் பயிர் (ரிலே)', s: 'இந்தப் பயிரை அறுக்கும் முன்பே அடுத்ததை விதைத்தல்', how: 'நிற்கும் பயிரின் அறுவடைக்குச் சில நாட்கள் அல்லது வாரங்களுக்கு முன்பே அதற்குள் அடுத்த பயிரின் விதைகளைத் தூவுகிறார்கள்; எ.கா. கிழக்கு மற்றும் மத்திய இந்தியாவில் நிற்கும் நெல்லில் மைசூர் பருப்பு, லாதிரஸ் அல்லது ஆளிவிதை தூவுதல், அல்லது காவிரி டெல்டா மற்றும் கடலோர ஆந்திராவில் அறுவடைக்குச் சற்று முன் நெல்லில் உளுந்து, பாசிப்பயறு விதைத்தல். புதிய பயிர் மண்ணில் மீதமுள்ள ஈரத்தைப் பயன்படுத்தி, வளர அதிக நேரம் பெறும்; அதனால் பாசனம் இல்லாமலும் இரண்டாம் பயிர் சாத்தியம்.' } },

{ id: 'rotation', cat: 'combo', icon: '🔄',
  k: ['rotation', 'crop rotation', 'फसल चक्र', 'फसल बदलना', 'पीक फेरपालट', 'फेरपालट', 'పంట మార్పిడి', 'మార్పిడి', 'பயிர் சுழற்சி', 'சுழற்சி'],
  en: { t: 'Crop rotation', s: 'Change the crop in a field every season', how: 'Do not grow the same crop in the same field season after season. Follow a cereal with a pulse or oilseed, for example paddy, then wheat, then summer moong. Rotation breaks the life cycle of pests, diseases and weeds, and pulses add nitrogen, so the next crop needs less fertilizer.' },
  hi: { t: 'फसल चक्र', s: 'हर मौसम में खेत की फसल बदलें', how: 'एक ही खेत में बार-बार वही फसल न उगाएँ। अनाज के बाद दाल या तिलहन लें, जैसे धान, फिर गेहूँ, फिर गर्मी में मूँग। फसल बदलने से कीट, रोग और खरपतवार का चक्र टूटता है, और दालें नाइट्रोजन बढ़ाती हैं, इसलिए अगली फसल को कम खाद चाहिए।' },
  mr: { t: 'पीक फेरपालट', s: 'प्रत्येक हंगामात शेतातील पीक बदला', how: 'एकाच शेतात पुन्हा पुन्हा तेच पीक घेऊ नका. तृणधान्यानंतर कडधान्य किंवा तेलबिया घ्या, जसे भात, मग गहू, मग उन्हाळी मूग. पीक बदलल्याने कीड, रोग आणि तणांचे चक्र तुटते, आणि कडधान्ये नत्र वाढवतात, त्यामुळे पुढच्या पिकाला कमी खत लागते.' },
  te: { t: 'పంట మార్పిడి', s: 'ప్రతి సీజన్‌లో పొలంలో పంట మార్చండి', how: 'ఒకే పొలంలో మళ్లీ మళ్లీ అదే పంట వేయకండి. ధాన్యం పంట తర్వాత పప్పు లేదా నూనె గింజల పంట వేయండి, ఉదాహరణకు వరి, తర్వాత గోధుమ, తర్వాత వేసవిలో పెసర. పంట మార్చడం వల్ల పురుగులు, తెగుళ్లు, కలుపు చక్రం తెగిపోతుంది, పప్పు పంటలు నత్రజని పెంచుతాయి, అందుకే తదుపరి పంటకు తక్కువ ఎరువు చాలు.' },
  ta: { t: 'பயிர் சுழற்சி', s: 'ஒவ்வொரு பருவத்திலும் வயலின் பயிரை மாற்றுங்கள்', how: 'ஒரே வயலில் மீண்டும் மீண்டும் அதே பயிரை வளர்க்காதீர்கள். தானியப் பயிருக்குப் பிறகு பயறு அல்லது எண்ணெய் வித்துப் பயிரை வளருங்கள்; எ.கா. நெல், பிறகு கோதுமை, பிறகு கோடையில் பாசிப்பயறு. பயிரை மாற்றுவதால் பூச்சி, நோய், களைகளின் சுழற்சி உடையும்; பயறு வகைகள் தழைச்சத்தைக் கூட்டுவதால் அடுத்த பயிருக்குக் குறைவான உரம் போதும்.' } },

{ id: 'ifs', cat: 'combo', icon: '🐓',
  k: ['fish farming', 'मछली पालन', 'मुर्गी पालन', 'बकरी पालन', 'पशु पालन', 'मत्स्य पालन', 'कुक्कुटपालन', 'शेळीपालन', 'చేపల పెంపకం', 'కోళ్ల పెంపకం', 'மீன் வளர்ப்பு', 'கோழி வளர்ப்பு', 'integrated farming', 'ifs', 'dairy', 'fish', 'poultry', 'goat', 'biogas', 'एकीकृत', 'एकीकृत खेती', 'डेयरी', 'मछली', 'मुर्गी', 'बकरी', 'पशुपालन', 'बायोगैस', 'एकात्मिक', 'दुग्धव्यवसाय', 'సమగ్ర వ్యవసాయం', 'పాడి', 'చేపలు', 'కోళ్లు', 'ஒருங்கிணைந்த பண்ணையம்', 'மீன்', 'கோழி', 'ஆடு'],
  en: { t: 'Integrated farming system', s: 'Crops, animals and fish working together', how: 'Crops are combined with dairy, goats, poultry, a fish pond, a biogas plant or bees on the same farm. The waste of one part feeds another: cow dung goes into biogas and compost, crop leftovers feed animals, and pond silt enriches the fields. Income comes in every month instead of once a season, and the risk from one crop failing is much lower.' },
  hi: { t: 'एकीकृत कृषि प्रणाली', s: 'फसल, पशु और मछली साथ मिलकर', how: 'एक ही खेत पर फसलों के साथ डेयरी, बकरी, मुर्गी, मछली का तालाब, बायोगैस या मधुमक्खी रखी जाती है। एक हिस्से का कचरा दूसरे के काम आता है: गोबर से बायोगैस और खाद बनती है, फसल के अवशेष पशुओं का चारा बनते हैं, और तालाब की गाद खेत को ताकत देती है। मौसम में एक बार की जगह हर महीने कमाई होती है, और एक फसल खराब होने का जोखिम बहुत कम हो जाता है।' },
  mr: { t: 'एकात्मिक शेती पद्धती', s: 'पिके, जनावरे आणि मासे एकत्र', how: 'एकाच शेतावर पिकांसोबत दुग्धव्यवसाय, शेळ्या, कोंबड्या, मत्स्यतळे, बायोगॅस किंवा मधमाश्या ठेवल्या जातात. एका भागाचा कचरा दुसऱ्याच्या कामी येतो: शेणापासून बायोगॅस आणि खत बनते, पिकांचे अवशेष जनावरांचा चारा बनतात, आणि तळ्याचा गाळ शेताला सुपीक करतो. हंगामात एकदाऐवजी दर महिन्याला उत्पन्न मिळते, आणि एक पीक बुडण्याचा धोका खूप कमी होतो.' },
  te: { t: 'సమగ్ర వ్యవసాయ విధానం', s: 'పంటలు, పశువులు, చేపలు కలిసి', how: 'ఒకే పొలంలో పంటలతో పాటు పాడి, మేకలు, కోళ్లు, చేపల చెరువు, బయోగ్యాస్ లేదా తేనెటీగలు పెంచుతారు. ఒక భాగం వ్యర్థం మరొక భాగానికి ఉపయోగపడుతుంది: పేడతో బయోగ్యాస్, ఎరువు తయారవుతాయి, పంట అవశేషాలు పశువులకు మేత అవుతాయి, చెరువు మట్టి పొలానికి బలం ఇస్తుంది. సీజన్‌కు ఒకసారి కాకుండా ప్రతి నెలా ఆదాయం వస్తుంది, ఒక పంట పోయే నష్ట భయం చాలా తగ్గుతుంది.' },
  ta: { t: 'ஒருங்கிணைந்த பண்ணையம்', s: 'பயிர், கால்நடை, மீன் சேர்ந்து', how: 'ஒரே பண்ணையில் பயிர்களுடன் பால் மாடுகள், ஆடுகள், கோழிகள், மீன் குளம், சாண எரிவாயு அல்லது தேனீக்கள் வளர்க்கப்படுகின்றன. ஒரு பகுதியின் கழிவு மற்றொன்றுக்குப் பயன்படும்: சாணம் எரிவாயுவாகவும் உரமாகவும் மாறும், பயிர்க் கழிவு கால்நடைத் தீவனமாகும், குளத்து வண்டல் வயலை வளமாக்கும். பருவத்துக்கு ஒருமுறை அல்லாமல் ஒவ்வொரு மாதமும் வருமானம் வரும்; ஒரு பயிர் தோற்கும் அபாயம் மிகக் குறையும்.' } },

{ id: 'agroforestry', cat: 'combo', icon: '🌲',
  k: ['agroforestry', 'trees', 'tree', 'timber', 'कृषि वानिकी', 'वानिकी', 'पेड़', 'पेड़ों', 'कृषी वनीकरण', 'झाडे', 'चेट्లు', 'చెట్లు', 'అటవీ', 'மரங்கள்', 'வேளாண் காடு', 'மரம்'],
  en: { t: 'Agroforestry (trees on the farm)', s: 'Grow trees along with crops', how: 'Fruit or timber trees are planted on field bunds or in wide rows with crops grown between them. Trees give extra income from fruit, fodder or wood, protect crops from strong winds, and their fallen leaves improve the soil. Choose trees that suit your area and plan their spacing and shade with the forest or agriculture department.' },
  hi: { t: 'कृषि वानिकी (खेत में पेड़)', s: 'फसलों के साथ पेड़ उगाना', how: 'फल या लकड़ी वाले पेड़ खेत की मेड़ों पर या चौड़ी कतारों में लगाए जाते हैं और उनके बीच फसल उगाई जाती है। पेड़ों से फल, चारे या लकड़ी की अतिरिक्त कमाई होती है, वे तेज़ हवा से फसल को बचाते हैं, और उनकी गिरी पत्तियाँ मिट्टी सुधारती हैं। अपने इलाके के अनुकूल पेड़ चुनें और उनकी दूरी व छाया की योजना वन या कृषि विभाग से बनवाएँ।' },
  mr: { t: 'कृषी वनीकरण (शेतात झाडे)', s: 'पिकांसोबत झाडे लावणे', how: 'फळझाडे किंवा लाकडाची झाडे बांधावर किंवा रुंद ओळींत लावली जातात आणि त्यांच्यामध्ये पिके घेतली जातात. झाडांपासून फळे, चारा किंवा लाकडाचे जादा उत्पन्न मिळते, ती जोराच्या वाऱ्यापासून पिकांचे रक्षण करतात, आणि गळलेली पाने जमीन सुधारतात. आपल्या भागाला योग्य झाडे निवडा आणि अंतर व सावलीचे नियोजन वन किंवा कृषी विभागाकडून करून घ्या.' },
  te: { t: 'వ్యవసాయ అటవీ పెంపకం (పొలంలో చెట్లు)', s: 'పంటలతో పాటు చెట్లు పెంచడం', how: 'పండ్ల లేదా కలప చెట్లను పొలం గట్ల మీద లేదా వెడల్పైన వరుసల్లో నాటి, వాటి మధ్య పంటలు వేస్తారు. చెట్ల నుంచి పండ్లు, మేత లేదా కలప ద్వారా అదనపు ఆదాయం వస్తుంది, అవి బలమైన గాలుల నుంచి పంటను కాపాడతాయి, రాలిన ఆకులు నేలను మెరుగుపరుస్తాయి. మీ ప్రాంతానికి సరిపడే చెట్లను ఎంచుకుని, దూరం, నీడ ప్రణాళికను అటవీ లేదా వ్యవసాయ శాఖతో వేసుకోండి.' },
  ta: { t: 'வேளாண் காடுகள் (பண்ணையில் மரங்கள்)', s: 'பயிர்களுடன் மரங்கள் வளர்த்தல்', how: 'பழ அல்லது மரக்கட்டை மரங்களை வரப்புகளில் அல்லது அகலமான வரிசைகளில் நட்டு, அவற்றுக்கு இடையே பயிர்கள் வளர்க்கப்படுகின்றன. மரங்களிலிருந்து பழம், தீவனம் அல்லது மரக்கட்டை மூலம் கூடுதல் வருமானம் கிடைக்கும்; அவை பலத்த காற்றிலிருந்து பயிரைக் காக்கும்; உதிரும் இலைகள் மண்ணை மேம்படுத்தும். உங்கள் பகுதிக்கு ஏற்ற மரங்களைத் தேர்ந்தெடுத்து, இடைவெளி மற்றும் நிழல் திட்டத்தை வனத் துறை அல்லது வேளாண் துறையுடன் வகுத்துக்கொள்ளுங்கள்.' } },

/* ======================= Soil & manure ======================= */
{ id: 'greenmanure', cat: 'soil', icon: '☘️',
  k: ['green manure', 'dhaincha', 'sunhemp', 'हरी खाद', 'ढैंचा', 'सनई', 'हिरवळीचे खत', 'हिरवळ', 'धैंचा', 'ताग', 'పచ్చిరొట్ట', 'జీలుగ', 'జనుము', 'பசுந்தாள் உரம்', 'பசுந்தாள்', 'தக்கைப்பூண்டு', 'சணப்பு'],
  en: { t: 'Green manure', s: 'Grow a crop and plough it into the soil', how: 'Fast-growing legumes like dhaincha or sunhemp are sown before the main crop and ploughed into the soil at about 40–50 days, before they flower. They add organic matter and nitrogen and make the soil softer, so the next crop needs less urea. A good fit before paddy in the summer gap.' },
  hi: { t: 'हरी खाद', s: 'फसल उगाकर मिट्टी में मिला देना', how: 'ढैंचा या सनई जैसी तेज़ बढ़ने वाली दलहनी फसल मुख्य फसल से पहले बोई जाती है और लगभग 40–50 दिन पर, फूल आने से पहले, जुताई करके मिट्टी में मिला दी जाती है। इससे मिट्टी में जैविक पदार्थ और नाइट्रोजन बढ़ते हैं और मिट्टी भुरभुरी होती है, इसलिए अगली फसल में कम यूरिया लगता है। गर्मी के खाली समय में धान से पहले यह बहुत उपयोगी है।' },
  mr: { t: 'हिरवळीचे खत', s: 'पीक वाढवून जमिनीत गाडणे', how: 'धैंचा किंवा ताग यांसारखे झपाट्याने वाढणारे कडधान्य पीक मुख्य पिकापूर्वी पेरले जाते आणि साधारण 40–50 दिवसांनी, फुले येण्यापूर्वी, नांगरून जमिनीत गाडले जाते. त्यामुळे जमिनीतील सेंद्रिय पदार्थ आणि नत्र वाढतात आणि जमीन भुसभुशीत होते, म्हणून पुढच्या पिकाला कमी युरिया लागतो. उन्हाळ्यातील रिकाम्या काळात भातापूर्वी हे खूप उपयोगी आहे.' },
  te: { t: 'పచ్చిరొట్ట ఎరువు', s: 'పంట పెంచి నేలలో కలియదున్నడం', how: 'జీలుగ లేదా జనుము వంటి వేగంగా పెరిగే పప్పు జాతి పంటను ప్రధాన పంటకు ముందు విత్తి, సుమారు 40–50 రోజుల్లో, పూత రాకముందే, దున్ని నేలలో కలుపుతారు. దీనివల్ల నేలలో సేంద్రియ పదార్థం, నత్రజని పెరుగుతాయి, నేల గుల్లబారుతుంది, అందుకే తదుపరి పంటకు తక్కువ యూరియా సరిపోతుంది. వేసవి ఖాళీ సమయంలో వరికి ముందు ఇది చాలా ఉపయోగం.' },
  ta: { t: 'பசுந்தாள் உரம்', s: 'பயிர் வளர்த்து மண்ணில் உழுதல்', how: 'தக்கைப்பூண்டு அல்லது சணப்பு போன்ற வேகமாக வளரும் பயறு வகைப் பயிரை முதன்மைப் பயிருக்கு முன் விதைத்து, சுமார் 40–50 நாட்களில், பூக்கும் முன்பே, உழுது மண்ணில் கலக்கிறார்கள். இதனால் மண்ணில் அங்ககப் பொருளும் தழைச்சத்தும் கூடும், மண் பொலபொலப்பாகும்; அடுத்த பயிருக்குக் குறைவான யூரியா போதும். கோடை இடைவெளியில் நெல்லுக்கு முன் இது மிகவும் பயனுள்ளது.' } },

{ id: 'biofert', cat: 'soil', icon: '🦠',
  k: ['culture', 'कल्चर', 'कल्चर', 'biofertilizer', 'bio fertilizer', 'biofertilizers', 'rhizobium', 'azotobacter', 'azospirillum', 'psb', 'जैव उर्वरक', 'जीवाणु खाद', 'राइजोबियम', 'एज़ोटोबैक्टर', 'जैविक खत', 'जीवाणू खत', 'రైజోబియం', 'జీవన ఎరువులు', 'உயிர் உரம்', 'உயிர் உரங்கள்', 'ரைசோபியம்'],
  en: { t: 'Bio-fertilizers', s: 'Helpful microbes that feed the crop', how: 'Packets of living, helpful bacteria: Rhizobium for pulses, Azotobacter or Azospirillum for cereals and vegetables, and PSB, which makes phosphorus in the soil available to plants. Mix with seed before sowing, dip seedling roots, or mix with compost and spread in the field. They are cheap and cut chemical fertilizer use; keep them in the shade and do not mix them with chemical fungicide at the same time.' },
  hi: { t: 'जैव उर्वरक', s: 'फसल को ताकत देने वाले अच्छे जीवाणु', how: 'ये ज़िंदा, फायदेमंद जीवाणुओं के पैकेट होते हैं: दालों के लिए राइजोबियम, अनाज और सब्ज़ियों के लिए एज़ोटोबैक्टर या एज़ोस्पिरिलम, और पीएसबी जो मिट्टी में पड़े फॉस्फोरस को पौधों के लिए उपलब्ध बनाता है। बुवाई से पहले बीज में मिलाएँ, पौध की जड़ें डुबोएँ, या कम्पोस्ट में मिलाकर खेत में डालें। ये सस्ते हैं और रासायनिक खाद की ज़रूरत घटाते हैं; इन्हें छाया में रखें और फफूंदनाशक दवा के साथ एक ही समय पर न मिलाएँ।' },
  mr: { t: 'जैविक खते (जीवाणू खते)', s: 'पिकाला पोषण देणारे उपयुक्त जीवाणू', how: 'ही जिवंत, उपयुक्त जीवाणूंची पाकिटे असतात: कडधान्यांसाठी रायझोबियम, तृणधान्ये आणि भाज्यांसाठी अॅझोटोबॅक्टर किंवा अॅझोस्पिरिलम, आणि पीएसबी जे जमिनीतील स्फुरद झाडांना उपलब्ध करून देते. पेरणीपूर्वी बियाण्याला चोळा, रोपांची मुळे बुडवा, किंवा कंपोस्टमध्ये मिसळून शेतात टाका. ही स्वस्त आहेत आणि रासायनिक खतांची गरज कमी करतात; ती सावलीत ठेवा आणि बुरशीनाशकासोबत एकाच वेळी मिसळू नका.' },
  te: { t: 'జీవన ఎరువులు', s: 'పంటకు బలం ఇచ్చే మేలు చేసే సూక్ష్మజీవులు', how: 'ఇవి సజీవమైన, మేలు చేసే బ్యాక్టీరియా ప్యాకెట్లు: పప్పు పంటలకు రైజోబియం, ధాన్యాలు, కూరగాయలకు అజటోబాక్టర్ లేదా అజోస్పైరిల్లం, నేలలోని భాస్వరాన్ని మొక్కలకు అందుబాటులోకి తెచ్చే పీఎస్‌బీ. విత్తే ముందు విత్తనాలకు పట్టించండి, నారు వేర్లను ముంచండి, లేదా కంపోస్ట్‌లో కలిపి పొలంలో చల్లండి. ఇవి చౌక, రసాయన ఎరువుల అవసరం తగ్గిస్తాయి; నీడలో ఉంచండి, శిలీంద్రనాశినితో ఒకేసారి కలపకండి.' },
  ta: { t: 'உயிர் உரங்கள்', s: 'பயிருக்குச் சத்து தரும் நன்மை நுண்ணுயிர்கள்', how: 'இவை உயிருள்ள, நன்மை செய்யும் பாக்டீரியா பொட்டலங்கள்: பயறு வகைகளுக்கு ரைசோபியம், தானியங்கள் மற்றும் காய்கறிகளுக்கு அசட்டோபாக்டர் அல்லது அசோஸ்பைரில்லம், மண்ணிலுள்ள மணிச்சத்தைச் செடிகளுக்குக் கிடைக்கச் செய்யும் பாஸ்போபாக்டீரியா. விதைப்பதற்கு முன் விதையுடன் கலக்கலாம், நாற்று வேர்களை நனைக்கலாம், அல்லது மட்கிய உரத்துடன் கலந்து வயலில் இடலாம். இவை மலிவானவை, ரசாயன உரத் தேவையைக் குறைக்கும்; நிழலில் வையுங்கள், பூஞ்சைக்கொல்லியுடன் ஒரே நேரத்தில் கலக்காதீர்கள்.' } },

{ id: 'jeevamrit', cat: 'soil', icon: '🥣',
  k: ['jeevamrit', 'jivamrut', 'jeevamrutham', 'fermented', 'fermentation', 'ferment', 'जीवामृत', 'जीवामृत घोल', 'किण्वित', 'फर्मेंटेशन', 'फर्मेंट', 'सड़ाना', 'गोमूत्र', 'आंबवलेले', 'आंबवणे', 'జీవామృతం', 'పులియబెట్టిన', 'పులియబెట్టడం', 'ఫర్మెంటేషన్', 'ஜீவாமிர்தம்', 'நொதித்த', 'நொதித்தல்'],
  en: { t: 'Jeevamrit (fermented mix)', s: 'A fermented liquid that wakes up soil life', how: 'A commonly used recipe: in 200 litres of water mix 10 kg fresh desi cow dung, 5–10 litres cow urine, 1–2 kg jaggery, 1–2 kg pulse flour and a handful of soil from your field. Keep it in the shade for 2 to 7 days, stirring with a stick twice a day, then give it with irrigation water or spray it after filtering. It increases useful microbes and earthworms in the soil; it is food for soil life, not a full replacement for nutrients the soil lacks.' },
  hi: { t: 'जीवामृत (किण्वित घोल)', s: 'मिट्टी के जीवों को जगाने वाला घोल', how: 'आम तौर पर इस्तेमाल होने वाला तरीका: 200 लीटर पानी में 10 किलो ताज़ा देसी गाय का गोबर, 5–10 लीटर गोमूत्र, 1–2 किलो गुड़, 1–2 किलो दाल का आटा और एक मुट्ठी अपने खेत की मिट्टी मिलाएँ। इसे छाया में 2 से 7 दिन रखें और दिन में दो बार लकड़ी से घुमाएँ, फिर सिंचाई के पानी के साथ दें या छानकर छिड़कें। इससे मिट्टी में अच्छे जीवाणु और केंचुए बढ़ते हैं; यह मिट्टी के जीवों का भोजन है, मिट्टी में कमी वाले सभी पोषक तत्वों की पूरी जगह नहीं लेता।' },
  mr: { t: 'जीवामृत (आंबवलेले द्रावण)', s: 'जमिनीतील जीवांना जागे करणारे द्रावण', how: 'सर्वसाधारणपणे वापरली जाणारी पद्धत: 200 लिटर पाण्यात 10 किलो ताजे देशी गायीचे शेण, 5–10 लिटर गोमूत्र, 1–2 किलो गूळ, 1–2 किलो डाळीचे पीठ आणि आपल्या शेतातील मूठभर माती मिसळा. हे सावलीत 2 ते 7 दिवस ठेवा आणि दिवसातून दोनदा काठीने ढवळा, मग पाटपाण्यासोबत द्या किंवा गाळून फवारा. यामुळे जमिनीत उपयुक्त जीवाणू आणि गांडुळे वाढतात; हे जमिनीतील जीवांचे अन्न आहे, जमिनीत कमी असलेल्या सर्व अन्नद्रव्यांची पूर्ण जागा घेत नाही.' },
  te: { t: 'జీవామృతం (పులియబెట్టిన ద్రావణం)', s: 'నేలలోని జీవాలను చురుకుగా చేసే ద్రావణం', how: 'సాధారణంగా వాడే విధానం: 200 లీటర్ల నీటిలో 10 కిలోల తాజా నాటు ఆవు పేడ, 5–10 లీటర్ల గోమూత్రం, 1–2 కిలోల బెల్లం, 1–2 కిలోల పప్పుల పిండి, గుప్పెడు మీ పొలం మట్టి కలపండి. దీన్ని నీడలో 2 నుంచి 7 రోజులు ఉంచి, రోజుకు రెండుసార్లు కర్రతో కలియబెట్టండి, తర్వాత సాగునీటితో పాటు ఇవ్వండి లేదా వడకట్టి పిచికారీ చేయండి. దీనివల్ల నేలలో మేలు చేసే సూక్ష్మజీవులు, వానపాములు పెరుగుతాయి; ఇది నేల జీవులకు ఆహారం, నేలలో లోపించిన అన్ని పోషకాలకు పూర్తి ప్రత్యామ్నాయం కాదు.' },
  ta: { t: 'ஜீவாமிர்தம் (நொதித்த கரைசல்)', s: 'மண்ணுயிர்களை உயிர்ப்பிக்கும் கரைசல்', how: 'பொதுவாகப் பயன்படுத்தப்படும் முறை: 200 லிட்டர் தண்ணீரில் 10 கிலோ புதிய நாட்டு மாட்டுச் சாணம், 5–10 லிட்டர் மாட்டுக் கோமியம், 1–2 கிலோ வெல்லம், 1–2 கிலோ பயறு மாவு, ஒரு கைப்பிடி உங்கள் வயல் மண் கலக்குங்கள். இதை நிழலில் 2 முதல் 7 நாட்கள் வைத்து, தினமும் இருமுறை குச்சியால் கலக்குங்கள்; பிறகு பாசன நீருடன் கொடுங்கள் அல்லது வடிகட்டித் தெளியுங்கள். இதனால் மண்ணில் நன்மை நுண்ணுயிர்களும் மண்புழுக்களும் பெருகும்; இது மண்ணுயிர்களுக்கான உணவு, மண்ணில் குறைவாக உள்ள எல்லாச் சத்துக்களுக்கும் முழு மாற்று அல்ல.' } },

{ id: 'vermi', cat: 'soil', icon: '♻️',
  k: ['vermicompost', 'vermi compost', 'earthworm', 'earthworms', 'compost', 'वर्मी कम्पोस्ट', 'वर्मी', 'केंचुआ', 'केंचुए', 'कम्पोस्ट', 'कंपोस्ट', 'गांडूळ खत', 'गांडूळ', 'गांडुळे', 'వర్మీకంపోస్ట్', 'వానపాము', 'వానపాములు', 'కంపోస్ట్', 'மண்புழு உரம்', 'மண்புழு', 'மட்கிய உரம்'],
  en: { t: 'Vermicompost', s: 'Earthworms turn waste into rich manure', how: 'Make a bed or pit in the shade, fill it with layers of crop waste and partly decomposed cow dung, and release composting earthworms (commonly Eisenia fetida). Keep it moist like a squeezed sponge and cover it with jute bags. In about 2 months it becomes dark, crumbly manure that improves soil and plant growth; it can also be sold.' },
  hi: { t: 'वर्मी कम्पोस्ट (केंचुआ खाद)', s: 'केंचुए कचरे को बढ़िया खाद बनाते हैं', how: 'छाया में एक बेड या गड्ढा बनाएँ, उसमें फसल के कचरे और अधसड़े गोबर की परतें भरें, और खाद बनाने वाले केंचुए (आमतौर पर आइसीनिया फेटिडा) छोड़ें। इसे निचोड़े हुए स्पंज जितना नम रखें और बोरी से ढकें। लगभग 2 महीने में यह काली, भुरभुरी खाद बन जाती है जो मिट्टी और पौधों की बढ़वार सुधारती है; इसे बेचा भी जा सकता है।' },
  mr: { t: 'गांडूळ खत', s: 'गांडुळे कचऱ्याचे उत्तम खत करतात', how: 'सावलीत एक वाफा किंवा खड्डा करा, त्यात पिकांचे अवशेष आणि अर्धवट कुजलेल्या शेणाचे थर भरा, आणि खत बनवणारी गांडुळे (सहसा आयसेनिया फेटिडा) सोडा. ते पिळलेल्या स्पंजइतके ओलसर ठेवा आणि गोणपाटाने झाका. साधारण 2 महिन्यांत ते काळे, भुसभुशीत खत बनते जे जमीन आणि झाडांची वाढ सुधारते; ते विकताही येते.' },
  te: { t: 'వర్మీకంపోస్ట్ (వానపాముల ఎరువు)', s: 'వానపాములు చెత్తను మంచి ఎరువుగా మారుస్తాయి', how: 'నీడలో ఒక బెడ్ లేదా గుంత చేసి, అందులో పంట వ్యర్థాలు, సగం కుళ్లిన పేడ పొరలుగా నింపి, ఎరువు చేసే వానపాములను (సాధారణంగా ఐసీనియా ఫెటిడా) వదలండి. పిండిన స్పాంజ్ అంత తేమగా ఉంచి, గోనె సంచులతో కప్పండి. సుమారు 2 నెలల్లో ఇది నల్లని, గుల్ల ఎరువుగా మారి నేలను, మొక్కల పెరుగుదలను మెరుగుపరుస్తుంది; దీన్ని అమ్మవచ్చు కూడా.' },
  ta: { t: 'மண்புழு உரம்', s: 'மண்புழுக்கள் கழிவை நல்ல உரமாக்கும்', how: 'நிழலில் ஒரு படுக்கை அல்லது குழி அமைத்து, அதில் பயிர்க் கழிவுகளையும் பாதி மட்கிய சாணத்தையும் அடுக்குகளாக நிரப்பி, உரம் தயாரிக்கும் மண்புழுக்களை (பொதுவாக ஐசீனியா ஃபெடிடா) விடுங்கள். பிழிந்த பஞ்சு அளவு ஈரமாக வைத்து, சணல் சாக்கால் மூடுங்கள். சுமார் 2 மாதங்களில் இது கருப்பான, பொலபொலப்பான உரமாக மாறி மண்ணையும் செடி வளர்ச்சியையும் மேம்படுத்தும்; இதை விற்கவும் செய்யலாம்.' } },

{ id: 'azolla', cat: 'soil', icon: '🍀',
  k: ['azolla', 'अज़ोला', 'अजोला', 'अझोला', 'అజోల్లా', 'அசோலா'],
  en: { t: 'Azolla', s: 'A tiny water fern that makes nitrogen', how: 'Azolla is a small fern that floats on water and takes nitrogen from the air. Grow it in a shallow pit lined with plastic sheet, with water, soil and a little cow dung; it multiplies very fast. Mix it into paddy fields as a green manure, or feed it fresh to cows, goats and poultry in small amounts along with their usual feed.' },
  hi: { t: 'अज़ोला', s: 'नाइट्रोजन बनाने वाली पानी की छोटी फ़र्न', how: 'अज़ोला पानी पर तैरने वाली छोटी फ़र्न है जो हवा से नाइट्रोजन लेती है। प्लास्टिक शीट बिछे उथले गड्ढे में पानी, मिट्टी और थोड़ा गोबर डालकर इसे उगाएँ; यह बहुत तेज़ी से बढ़ती है। धान के खेत में हरी खाद की तरह मिलाएँ, या गाय, बकरी और मुर्गियों को रोज़ के चारे के साथ थोड़ी मात्रा में ताज़ा खिलाएँ।' },
  mr: { t: 'अझोला', s: 'नत्र तयार करणारी पाण्यावरची लहान वनस्पती', how: 'अझोला ही पाण्यावर तरंगणारी लहान वनस्पती आहे जी हवेतील नत्र घेते. प्लास्टिक कागद अंथरलेल्या उथळ खड्ड्यात पाणी, माती आणि थोडे शेण टाकून ती वाढवा; ती खूप झपाट्याने वाढते. भात शेतात हिरवळीच्या खतासारखी मिसळा, किंवा गायी, शेळ्या आणि कोंबड्यांना नेहमीच्या खाद्यासोबत थोड्या प्रमाणात ताजी खाऊ घाला.' },
  te: { t: 'అజోల్లా', s: 'నత్రజని తయారు చేసే చిన్న నీటి మొక్క', how: 'అజోల్లా నీటిపై తేలే చిన్న మొక్క, గాలి నుంచి నత్రజనిని తీసుకుంటుంది. ప్లాస్టిక్ షీట్ పరిచిన లోతులేని గుంతలో నీరు, మట్టి, కొంచెం పేడ వేసి పెంచండి; ఇది చాలా వేగంగా పెరుగుతుంది. వరి పొలంలో పచ్చిరొట్ట ఎరువులా కలపండి, లేదా ఆవులు, మేకలు, కోళ్లకు రోజువారీ మేతతో పాటు కొద్ది మొత్తంలో తాజాగా పెట్టండి.' },
  ta: { t: 'அசோலா', s: 'தழைச்சத்து தரும் சிறிய நீர்ச் செடி', how: 'அசோலா நீரில் மிதக்கும் சிறிய செடி; காற்றிலிருந்து தழைச்சத்தை எடுத்துக்கொள்ளும். பிளாஸ்டிக் தாள் விரித்த ஆழமற்ற குழியில் நீர், மண், சிறிது சாணம் இட்டு வளருங்கள்; இது மிக வேகமாகப் பெருகும். நெல் வயலில் பசுந்தாள் உரமாகக் கலக்கலாம், அல்லது மாடு, ஆடு, கோழிகளுக்கு வழக்கமான தீவனத்துடன் சிறிதளவு பச்சையாகக் கொடுக்கலாம்.' } },

{ id: 'zerotill', cat: 'soil', icon: '🚜',
  k: ['zero tillage', 'zero till', 'no till', 'happy seeder', 'stubble', 'parali', 'decomposer', 'ज़ीरो टिल', 'जीरो टिलेज', 'हैप्पी सीडर', 'पराली', 'डीकंपोज़र', 'डिकंपोजर', 'बिना जुताई', 'जुताई', 'शून्य मशागत', 'पेंढा', 'జీరో టిల్', 'హ్యాపీ సీడర్', 'దుక్కి', 'గడ్డి', 'உழவில்லா', 'வைக்கோல்', 'ஹேப்பி சீடர்'],
  en: { t: 'Zero tillage and no stubble burning', s: 'Sow without ploughing; keep residue in the field', how: 'Wheat can be sown straight into harvested paddy fields with a Happy Seeder or zero-till drill, without ploughing or burning the straw. The straw stays as mulch and saves moisture, while time, diesel and ploughing cost are saved. Straw can also be decomposed in the field with a decomposer spray such as the Pusa decomposer. Machines are often available on rent at custom hiring centres.' },
  hi: { t: 'बिना जुताई बुवाई, पराली न जलाएँ', s: 'बिना जोते बोएँ, अवशेष खेत में रखें', how: 'धान कटे खेत में हैप्पी सीडर या ज़ीरो टिल ड्रिल से बिना जुताई और बिना पराली जलाए सीधे गेहूँ बोया जा सकता है। पराली मल्च बनकर नमी बचाती है, और समय, डीज़ल व जुताई का खर्च बचता है। पूसा डीकंपोज़र जैसे घोल के छिड़काव से पराली खेत में ही गलाई भी जा सकती है। मशीनें अक्सर कस्टम हायरिंग केंद्रों पर किराये पर मिल जाती हैं।' },
  mr: { t: 'शून्य मशागत आणि अवशेष न जाळणे', s: 'नांगरणीशिवाय पेरणी, अवशेष शेतातच', how: 'भात काढलेल्या शेतात हॅपी सीडर किंवा झिरो टिल ड्रिलने नांगरणी न करता आणि पेंढा न जाळता थेट गहू पेरता येतो. पेंढा आच्छादन बनून ओलावा टिकवतो, आणि वेळ, डिझेल व नांगरणीचा खर्च वाचतो. पुसा डिकंपोजरसारख्या द्रावणाच्या फवारणीने पेंढा शेतातच कुजवताही येतो. यंत्रे अनेकदा अवजारे बँकेत (कस्टम हायरिंग केंद्र) भाड्याने मिळतात.' },
  te: { t: 'దుక్కి లేని సాగు, గడ్డి కాల్చకపోవడం', s: 'దున్నకుండా విత్తడం, అవశేషాలు పొలంలోనే', how: 'వరి కోసిన పొలంలో హ్యాపీ సీడర్ లేదా జీరో టిల్ డ్రిల్‌తో దున్నకుండా, గడ్డి కాల్చకుండా నేరుగా గోధుమ విత్తవచ్చు. గడ్డి మల్చ్‌గా ఉండి తేమను కాపాడుతుంది, సమయం, డీజిల్, దుక్కి ఖర్చు ఆదా అవుతాయి. పూసా డీకంపోజర్ వంటి ద్రావణం పిచికారీతో గడ్డిని పొలంలోనే కుళ్లబెట్టవచ్చు. యంత్రాలు తరచూ కస్టమ్ హైరింగ్ కేంద్రాల్లో అద్దెకు దొరుకుతాయి.' },
  ta: { t: 'உழவில்லா விதைப்பு, தாள் எரிக்காமை', s: 'உழாமல் விதைத்தல், கழிவை வயலிலேயே விடுதல்', how: 'நெல் அறுத்த வயலில் ஹேப்பி சீடர் அல்லது ஜீரோ டில் டிரில் கொண்டு உழாமலும் வைக்கோலை எரிக்காமலும் நேரடியாகக் கோதுமை விதைக்கலாம். வைக்கோல் மூடாக்காக இருந்து ஈரத்தைக் காக்கும்; நேரம், டீசல், உழவுச் செலவு மிச்சமாகும். பூசா டிகம்போசர் போன்ற கரைசல் தெளித்து வைக்கோலை வயலிலேயே மட்கச் செய்யலாம். இயந்திரங்கள் பெரும்பாலும் வாடகை மையங்களில் கிடைக்கும்.' } },

/* ======================= Water & sowing ======================= */
{ id: 'drip', cat: 'water', icon: '💧',
  k: ['drip', 'drip irrigation', 'fertigation', 'ड्रिप', 'टपक', 'टपक सिंचाई', 'फर्टिगेशन', 'ठिबक', 'ठिबक सिंचन', 'బిందు', 'బిందు సేద్యం', 'డ్రిప్', 'ఫర్టిగేషన్', 'சொட்டு நீர்', 'சொட்டு', 'உரப்பாசனம்'],
  en: { t: 'Drip irrigation and fertigation', s: 'Water and fertilizer drop by drop at the roots', how: 'Pipes with drippers give water slowly at each plant’s root, so far less water is wasted than in flood irrigation and fewer weeds grow between rows. Water-soluble fertilizer can be given through the same pipes in small doses (fertigation), so less fertilizer is wasted. There is a subsidy for drip systems under the Pradhan Mantri Krishi Sinchayee Yojana; flush the pipes and clean the filter regularly.' },
  hi: { t: 'ड्रिप सिंचाई और फर्टिगेशन', s: 'जड़ों में बूँद-बूँद पानी और खाद', how: 'ड्रिपर लगी पाइपें हर पौधे की जड़ में धीरे-धीरे पानी देती हैं, इसलिए खुली सिंचाई से बहुत कम पानी बर्बाद होता है और कतारों के बीच खरपतवार भी कम उगते हैं। पानी में घुलने वाली खाद इन्हीं पाइपों से थोड़ी-थोड़ी मात्रा में दी जा सकती है (फर्टिगेशन), जिससे खाद कम बर्बाद होती है। प्रधानमंत्री कृषि सिंचाई योजना में ड्रिप पर सब्सिडी मिलती है; पाइपों की धुलाई और फ़िल्टर की सफ़ाई नियमित करें।' },
  mr: { t: 'ठिबक सिंचन आणि फर्टिगेशन', s: 'मुळांशी थेंबाथेंबाने पाणी आणि खत', how: 'ड्रिपर लावलेल्या नळ्या प्रत्येक झाडाच्या मुळाशी हळूहळू पाणी देतात, त्यामुळे पाटपाण्यापेक्षा खूप कमी पाणी वाया जाते आणि ओळींमध्ये तणही कमी येते. पाण्यात विरघळणारी खते याच नळ्यांतून थोड्या थोड्या प्रमाणात देता येतात (फर्टिगेशन), त्यामुळे खत कमी वाया जाते. प्रधानमंत्री कृषी सिंचाई योजनेत ठिबकसाठी अनुदान मिळते; नळ्यांची धुलाई आणि फिल्टरची सफाई नियमित करा.' },
  te: { t: 'బిందు సేద్యం, ఫర్టిగేషన్', s: 'వేర్లకు చుక్క చుక్కగా నీరు, ఎరువు', how: 'డ్రిప్పర్లు ఉన్న పైపులు ప్రతి మొక్క వేరుకు నెమ్మదిగా నీరు ఇస్తాయి, అందుకే వరద పారుదల కంటే చాలా తక్కువ నీరు వృథా అవుతుంది, వరుసల మధ్య కలుపు కూడా తక్కువ. నీటిలో కరిగే ఎరువులను ఇవే పైపుల ద్వారా కొద్ది కొద్దిగా ఇవ్వవచ్చు (ఫర్టిగేషన్), ఎరువు వృథా తగ్గుతుంది. ప్రధానమంత్రి కృషి సించాయీ యోజన కింద బిందు పరికరాలకు సబ్సిడీ ఉంది; పైపులను కడగడం, ఫిల్టర్ శుభ్రం చేయడం క్రమం తప్పకుండా చేయండి.' },
  ta: { t: 'சொட்டு நீர்ப்பாசனமும் உரப்பாசனமும்', s: 'வேருக்குத் துளித்துளியாக நீரும் உரமும்', how: 'சொட்டுவான் உள்ள குழாய்கள் ஒவ்வொரு செடியின் வேருக்கும் மெதுவாக நீர் தரும்; அதனால் வாய்க்கால் பாசனத்தை விட மிகக் குறைவான நீரே வீணாகும், வரிசைகளுக்கு இடையே களையும் குறையும். நீரில் கரையும் உரங்களை இதே குழாய்கள் வழியாகச் சிறிது சிறிதாகக் கொடுக்கலாம் (உரப்பாசனம்); உரம் வீணாவது குறையும். பிரதம மந்திரி கிருஷி சிஞ்சாயி யோஜனாவில் சொட்டு அமைப்புக்கு மானியம் உண்டு; குழாய்களைக் கழுவுவதையும் வடிகட்டியைச் சுத்தம் செய்வதையும் தவறாமல் செய்யுங்கள்.' } },

{ id: 'mulch', cat: 'water', icon: '🍂',
  k: ['mulch', 'mulching', 'plastic mulch', 'मल्च', 'मल्चिंग', 'पलवार', 'पुआल', 'आच्छादन', 'मल्चिंग पेपर', 'మల్చ్', 'మల్చింగ్', 'మూడాక్కు', 'மூடாக்கு', 'மல்ச்சிங்'],
  en: { t: 'Mulching', s: 'Cover the soil to save water and stop weeds', how: 'Cover the soil around plants with straw, dry leaves or plastic mulch film. On raised vegetable or strawberry beds, film is laid and plants are set through holes in it. Mulch keeps moisture in, stops weeds, keeps fruits off the soil so they stay clean, and in winter keeps the soil warmer; organic mulch also turns into manure over time.' },
  hi: { t: 'मल्चिंग (पलवार)', s: 'मिट्टी ढककर पानी बचाना और खरपतवार रोकना', how: 'पौधों के आसपास की मिट्टी को पुआल, सूखी पत्तियों या प्लास्टिक मल्च फ़िल्म से ढकें। सब्ज़ी या स्ट्रॉबेरी की ऊँची क्यारियों पर फ़िल्म बिछाकर उसके छेदों में पौधे लगाए जाते हैं। मल्च नमी बचाता है, खरपतवार रोकता है, फलों को मिट्टी से दूर रखकर साफ़ रखता है, और सर्दी में मिट्टी को गर्म रखता है; जैविक मल्च समय के साथ खाद भी बन जाता है।' },
  mr: { t: 'आच्छादन (मल्चिंग)', s: 'माती झाकून पाणी वाचवणे आणि तण रोखणे', how: 'झाडांभोवतीची माती पेंढा, वाळलेली पाने किंवा प्लास्टिक मल्चिंग पेपरने झाका. भाजीपाला किंवा स्ट्रॉबेरीच्या गादी वाफ्यांवर पेपर अंथरून त्याच्या छिद्रांत रोपे लावली जातात. आच्छादन ओलावा टिकवते, तण रोखते, फळे मातीपासून दूर ठेवून स्वच्छ ठेवते, आणि हिवाळ्यात माती उबदार ठेवते; सेंद्रिय आच्छादन कालांतराने खतही बनते.' },
  te: { t: 'మల్చింగ్', s: 'నేలను కప్పి నీరు ఆదా, కలుపు నివారణ', how: 'మొక్కల చుట్టూ నేలను గడ్డి, ఎండిన ఆకులు లేదా ప్లాస్టిక్ మల్చ్ షీట్‌తో కప్పండి. కూరగాయలు లేదా స్ట్రాబెర్రీ ఎత్తు మడులపై షీట్ పరిచి, దాని రంధ్రాల్లో మొక్కలు నాటుతారు. మల్చ్ తేమను నిలుపుతుంది, కలుపును ఆపుతుంది, కాయలు నేలకు తగలకుండా శుభ్రంగా ఉంచుతుంది, చలికాలంలో నేలను వెచ్చగా ఉంచుతుంది; సేంద్రియ మల్చ్ కాలక్రమంలో ఎరువుగా కూడా మారుతుంది.' },
  ta: { t: 'மூடாக்கு (மல்ச்சிங்)', s: 'மண்ணை மூடி நீர் சேமிப்பு, களை தடுப்பு', how: 'செடிகளைச் சுற்றியுள்ள மண்ணை வைக்கோல், காய்ந்த இலைகள் அல்லது பிளாஸ்டிக் மூடாக்குத் தாளால் மூடுங்கள். காய்கறி அல்லது ஸ்ட்ராபெர்ரி மேட்டுப் பாத்திகளில் தாளை விரித்து அதன் துளைகளில் நாற்றுகளை நடுகிறார்கள். மூடாக்கு ஈரத்தைக் காக்கும், களையைத் தடுக்கும், காய்கள் மண்ணில் படாமல் சுத்தமாக வைக்கும், குளிர்காலத்தில் மண்ணை வெதுவெதுப்பாக வைக்கும்; அங்கக மூடாக்கு காலப்போக்கில் உரமாகவும் மாறும்.' } },

{ id: 'farmpond', cat: 'water', icon: '🌧️',
  k: ['farm pond', 'pond', 'rainwater', 'rain water', 'water harvesting', 'तालाब', 'खेत तालाब', 'वर्षा जल', 'बारिश का पानी', 'जल संचयन', 'शेततळे', 'तळे', 'కుంట', 'పొలం కుంట', 'వర్షపు నీరు', 'குட்டை', 'பண்ணைக் குட்டை', 'மழைநீர்'],
  en: { t: 'Farm pond (rainwater harvesting)', s: 'Store rain water for dry days', how: 'A pond dug in the lowest corner of the field collects rain runoff; lining it with plastic sheet stops seepage. The stored water can save the crop during a dry spell or give an extra irrigation for a second crop, and fish can be raised in it. Many state schemes give help for farm ponds; ask your agriculture office.' },
  hi: { t: 'खेत तालाब (वर्षा जल संचयन)', s: 'बारिश का पानी सूखे दिनों के लिए जमा करें', how: 'खेत के सबसे निचले कोने में खोदा गया तालाब बारिश में बहता पानी जमा करता है; प्लास्टिक शीट बिछाने से पानी रिसता नहीं। जमा पानी सूखे के दौर में फसल बचा सकता है या दूसरी फसल के लिए एक अतिरिक्त सिंचाई दे सकता है, और इसमें मछली भी पाली जा सकती है। कई राज्यों की योजनाओं में खेत तालाब के लिए मदद मिलती है; अपने कृषि कार्यालय से पूछें।' },
  mr: { t: 'शेततळे (पावसाचे पाणी साठवण)', s: 'पावसाचे पाणी कोरड्या दिवसांसाठी साठवा', how: 'शेताच्या सर्वात सखल कोपऱ्यात खोदलेले तळे पावसात वाहणारे पाणी साठवते; प्लास्टिक कागद अंथरल्याने पाणी झिरपत नाही. साठवलेले पाणी पावसाच्या खंडात पीक वाचवू शकते किंवा दुसऱ्या पिकासाठी एक जादा पाणी देऊ शकते, आणि त्यात मासेही पाळता येतात. अनेक राज्य योजनांमध्ये शेततळ्यासाठी मदत मिळते; आपल्या कृषी कार्यालयात विचारा.' },
  te: { t: 'పొలం కుంట (వర్షపు నీటి సంరక్షణ)', s: 'వర్షపు నీటిని పొడి రోజుల కోసం నిల్వ చేయండి', how: 'పొలంలోని అత్యంత పల్లపు మూలలో తవ్విన కుంట వర్షపు ప్రవాహ నీటిని నిల్వ చేస్తుంది; ప్లాస్టిక్ షీట్ పరిస్తే నీరు ఇంకిపోదు. నిల్వ నీరు వర్షాభావ సమయంలో పంటను కాపాడుతుంది లేదా రెండో పంటకు ఒక అదనపు తడి ఇవ్వగలదు, అందులో చేపలు కూడా పెంచవచ్చు. చాలా రాష్ట్ర పథకాలు పొలం కుంటలకు సహాయం ఇస్తాయి; మీ వ్యవసాయ కార్యాలయంలో అడగండి.' },
  ta: { t: 'பண்ணைக் குட்டை (மழைநீர் சேகரிப்பு)', s: 'மழைநீரை வறண்ட நாட்களுக்குச் சேமியுங்கள்', how: 'வயலின் மிகத் தாழ்வான மூலையில் தோண்டிய குட்டை மழையில் ஓடும் நீரைச் சேமிக்கும்; பிளாஸ்டிக் தாள் விரித்தால் நீர் கசியாது. சேமித்த நீர் வறட்சிக் காலத்தில் பயிரைக் காக்கும் அல்லது இரண்டாம் பயிருக்கு ஒரு கூடுதல் பாசனம் தரும்; அதில் மீனும் வளர்க்கலாம். பல மாநிலத் திட்டங்கள் பண்ணைக் குட்டைகளுக்கு உதவி தருகின்றன; உங்கள் வேளாண் அலுவலகத்தில் கேளுங்கள்.' } },

{ id: 'raisedbed', cat: 'water', icon: '🟫',
  k: ['raised bed', 'raised beds', 'ridge', 'furrow', 'bbf', 'broad bed', 'क्यारी', 'ऊँची क्यारी', 'मेड़', 'नाली', 'रिज', 'बेड', 'गादी वाफा', 'सरी वरंबा', 'सरी', 'वरंबा', 'మడులు', 'ఎత్తు మడులు', 'బోదె', 'బోదెలు', 'பாத்தி', 'மேட்டுப் பாத்தி', 'பார்', 'சால்'],
  en: { t: 'Raised beds and ridge sowing', s: 'Sow on beds or ridges instead of flat land', how: 'Crops are sown on raised beds or ridges with furrows in between that carry water, for example wheat on beds, or soybean on broad beds with furrows (BBF). Irrigation water is saved, extra rain drains away through the furrows so roots do not rot, and the crop stands better. Bed planters and ridgers that do this are available on rent.' },
  hi: { t: 'ऊँची क्यारी और मेड़ पर बुवाई', s: 'समतल की जगह क्यारी या मेड़ पर बोएँ', how: 'फसल ऊँची क्यारियों या मेड़ों पर बोई जाती है और बीच की नालियाँ पानी ले जाती हैं, जैसे क्यारियों पर गेहूँ, या चौड़ी क्यारी-नाली (BBF) विधि से सोयाबीन। सिंचाई का पानी बचता है, ज़्यादा बारिश का पानी नालियों से निकल जाता है ताकि जड़ें न सड़ें, और फसल बेहतर खड़ी रहती है। यह काम करने वाले बेड प्लांटर और रिजर किराये पर मिलते हैं।' },
  mr: { t: 'गादी वाफा आणि सरी वरंबा', s: 'सपाट जमिनीऐवजी वाफ्यावर किंवा वरंब्यावर पेरा', how: 'पिके उंच गादी वाफ्यांवर किंवा वरंब्यांवर पेरली जातात आणि मधल्या सऱ्या पाणी वाहून नेतात, जसे वाफ्यावर गहू, किंवा रुंद वरंबा-सरी (BBF) पद्धतीने सोयाबीन. सिंचनाचे पाणी वाचते, जास्त पावसाचे पाणी सऱ्यांमधून निघून जाते त्यामुळे मुळे कुजत नाहीत, आणि पीक चांगले उभे राहते. हे काम करणारी यंत्रे भाड्याने मिळतात.' },
  te: { t: 'ఎత్తు మడులు, బోదెలపై విత్తడం', s: 'చదునుకు బదులు మడులు లేదా బోదెలపై విత్తండి', how: 'పంటలను ఎత్తు మడులు లేదా బోదెలపై విత్తుతారు, మధ్యలోని కాలువలు నీటిని తీసుకెళ్తాయి, ఉదాహరణకు మడులపై గోధుమ, లేదా వెడల్పాటి మడి-కాలువ (BBF) పద్ధతిలో సోయాబీన్. సాగునీరు ఆదా అవుతుంది, అధిక వర్షపు నీరు కాలువల ద్వారా బయటకు పోతుంది కాబట్టి వేర్లు కుళ్లవు, పంట బాగా నిలబడుతుంది. ఈ పని చేసే బెడ్ ప్లాంటర్లు, రిడ్జర్లు అద్దెకు దొరుకుతాయి.' },
  ta: { t: 'மேட்டுப் பாத்தியும் பார் விதைப்பும்', s: 'சமதளத்துக்குப் பதில் பாத்தி அல்லது பாரில் விதையுங்கள்', how: 'பயிர்களை மேட்டுப் பாத்திகள் அல்லது பார்களில் விதைத்து, இடையிலுள்ள சால்கள் வழியாக நீர் பாய்ச்சுகிறார்கள்; எ.கா. பாத்திகளில் கோதுமை, அல்லது அகலப் பாத்தி-சால் (BBF) முறையில் சோயாபீன். பாசன நீர் மிச்சமாகும், அதிக மழைநீர் சால்கள் வழியாக வடிந்துவிடுவதால் வேர் அழுகாது, பயிர் நன்றாக நிற்கும். இதைச் செய்யும் இயந்திரங்கள் வாடகைக்குக் கிடைக்கும்.' } },

{ id: 'sri', cat: 'water', icon: '🌾',
  k: ['sri', 'system of rice intensification', 'श्री विधि', 'श्री', 'एसआरआई', 'धान', 'श्री पद्धत', 'శ్రీ వరి', 'శ్రీ', 'వరి', 'திருந்திய நெல்', 'எஸ்ஆர்ஐ', 'நெல்'],
  en: { t: 'SRI method of paddy', s: 'Fewer, younger seedlings and less water', how: 'In the System of Rice Intensification, young seedlings about 8–12 days old are transplanted one per spot in a square pattern of about 25 × 25 cm. The field is kept moist and allowed to dry a little between irrigations instead of staying flooded, and weeds are pressed into the soil with a cono-weeder. Much less seed and water are needed and each plant makes more tillers.' },
  hi: { t: 'धान की श्री (SRI) विधि', s: 'कम और छोटी पौध, कम पानी', how: 'धान सघनीकरण प्रणाली (श्री विधि) में लगभग 8–12 दिन की छोटी पौध एक जगह पर एक-एक, करीब 25 × 25 सेंटीमीटर की चौकोर दूरी पर रोपी जाती है। खेत में हमेशा पानी भरा रखने की जगह नमी रखी जाती है और सिंचाइयों के बीच थोड़ा सूखने दिया जाता है, और कोनो वीडर से खरपतवार मिट्टी में मिला दिए जाते हैं। बीज और पानी बहुत कम लगता है और हर पौधे में ज़्यादा कल्ले निकलते हैं।' },
  mr: { t: 'भाताची श्री (SRI) पद्धत', s: 'कमी आणि कोवळी रोपे, कमी पाणी', how: 'श्री पद्धतीत साधारण 8–12 दिवसांची कोवळी रोपे एका जागी एक, सुमारे 25 × 25 सेंटीमीटरच्या चौरस अंतरावर लावली जातात. शेतात सतत पाणी साचवण्याऐवजी ओलावा ठेवला जातो आणि दोन पाण्यांच्या मध्ये थोडे सुकू दिले जाते, आणि कोनो वीडरने तण मातीत मिसळले जाते. बियाणे आणि पाणी खूप कमी लागते आणि प्रत्येक रोपाला जास्त फुटवे येतात.' },
  te: { t: 'వరిలో శ్రీ (SRI) పద్ధతి', s: 'తక్కువ, లేత నారు, తక్కువ నీరు', how: 'శ్రీ వరి సాగులో సుమారు 8–12 రోజుల లేత నారును ఒక్కో చోట ఒక్కొక్కటి చొప్పున, సుమారు 25 × 25 సెంటీమీటర్ల చతురస్ర దూరంలో నాటుతారు. పొలంలో ఎప్పుడూ నీరు నిలిపి ఉంచకుండా తేమగా ఉంచి, తడుల మధ్య కొంచెం ఆరనిస్తారు, కోనో వీడర్‌తో కలుపును నేలలో కలుపుతారు. విత్తనం, నీరు చాలా తక్కువ అవసరం, ప్రతి మొక్కకు ఎక్కువ పిలకలు వస్తాయి.' },
  ta: { t: 'திருந்திய நெல் சாகுபடி (SRI)', s: 'குறைவான, இளம் நாற்று; குறைந்த நீர்', how: 'திருந்திய நெல் சாகுபடியில் சுமார் 8–12 நாள் இளம் நாற்றுகளை ஓரிடத்துக்கு ஒன்றாக, ஏறத்தாழ 25 × 25 சென்டிமீட்டர் சதுர இடைவெளியில் நடுகிறார்கள். வயலில் எப்போதும் நீர் தேக்காமல் ஈரமாக வைத்து, பாசனங்களுக்கு இடையே சற்று காயவிடுகிறார்கள்; கோனோ வீடர் கொண்டு களைகளை மண்ணில் அமுக்குகிறார்கள். விதையும் நீரும் மிகக் குறைவாகத் தேவைப்படும்; ஒவ்வொரு செடியிலும் அதிகத் தூர்கள் வரும்.' } },

{ id: 'dsr', cat: 'water', icon: '🌾',
  k: ['dsr', 'direct seeded rice', 'direct seeding', 'direct sowing', 'सीधी बुवाई', 'डीएसआर', 'धान की सीधी बुवाई', 'थेट पेरणी', 'नेरुगा', 'నేరుగా విత్తడం', 'వెదజల్లే', 'நேரடி நெல்', 'நேரடி விதைப்பு'],
  en: { t: 'Direct seeded rice (DSR)', s: 'Sow paddy seed directly, no nursery or puddling', how: 'Paddy seed is sown straight into the field with a seed drill, without raising a nursery, puddling or transplanting. It saves water, labour and time, and the field is ready earlier for the next crop. Weeds are the main challenge, so timely weeding or a herbicide as advised locally is a must, along with good land levelling.' },
  hi: { t: 'धान की सीधी बुवाई (DSR)', s: 'नर्सरी और कद्दू किए बिना सीधे बीज बोना', how: 'धान का बीज सीड ड्रिल से सीधे खेत में बोया जाता है, बिना नर्सरी, कद्दू (पडलिंग) या रोपाई के। इससे पानी, मज़दूरी और समय बचता है, और खेत अगली फसल के लिए जल्दी खाली होता है। सबसे बड़ी चुनौती खरपतवार है, इसलिए समय पर निराई या स्थानीय सलाह के अनुसार खरपतवारनाशी ज़रूरी है, साथ में खेत अच्छा समतल होना चाहिए।' },
  mr: { t: 'भाताची थेट पेरणी (DSR)', s: 'रोपवाटिका आणि चिखलणीशिवाय थेट बी पेरणे', how: 'भाताचे बी पेरणी यंत्राने थेट शेतात पेरले जाते, रोपवाटिका, चिखलणी किंवा पुनर्लागवडीशिवाय. यामुळे पाणी, मजुरी आणि वेळ वाचतो, आणि शेत पुढच्या पिकासाठी लवकर रिकामे होते. तण हे सर्वात मोठे आव्हान आहे, म्हणून वेळेवर खुरपणी किंवा स्थानिक सल्ल्यानुसार तणनाशक आवश्यक आहे, सोबत जमीन चांगली सपाट असावी.' },
  te: { t: 'వరి నేరుగా విత్తడం (DSR)', s: 'నారుమడి, దమ్ము లేకుండా నేరుగా విత్తనం', how: 'వరి విత్తనాన్ని సీడ్ డ్రిల్‌తో నేరుగా పొలంలో విత్తుతారు, నారుమడి, దమ్ము చేయడం, నాట్లు వేయడం లేకుండా. దీనివల్ల నీరు, కూలీ, సమయం ఆదా అవుతాయి, తదుపరి పంటకు పొలం త్వరగా ఖాళీ అవుతుంది. కలుపు ప్రధాన సవాల్, కాబట్టి సకాలంలో కలుపు తీయడం లేదా స్థానిక సలహా మేరకు కలుపు మందు తప్పనిసరి, పొలం బాగా చదునుగా ఉండాలి.' },
  ta: { t: 'நேரடி நெல் விதைப்பு (DSR)', s: 'நாற்றங்கால், சேறு இல்லாமல் நேரடி விதைப்பு', how: 'நெல் விதையை விதைப்புக் கருவியால் நேரடியாக வயலில் விதைக்கிறார்கள்; நாற்றங்கால், சேறு கலக்குதல், நடவு எதுவும் இல்லை. இதனால் நீர், கூலி, நேரம் மிச்சமாகும்; அடுத்த பயிருக்கு வயல் விரைவில் தயாராகும். களைதான் முக்கியச் சவால்; எனவே சரியான நேரத்தில் களையெடுத்தல் அல்லது உள்ளூர் ஆலோசனைப்படி களைக்கொல்லி அவசியம்; நிலமும் நன்கு சமன் செய்யப்பட்டிருக்க வேண்டும்.' } },

{ id: 'laser', cat: 'water', icon: '📏',
  k: ['laser', 'laser levelling', 'laser leveling', 'land levelling', 'लेज़र', 'लेजर', 'समतल', 'समतलीकरण', 'सपाटीकरण', 'లేజర్', 'చదును', 'லேசர்', 'சமன்'],
  en: { t: 'Laser land levelling', s: 'Make the field perfectly flat', how: 'A tractor-drawn leveller guided by a laser makes the field surface almost perfectly flat. Water then spreads evenly, so irrigation needs less water and time, the crop grows evenly, and fertilizer is used better. It is usually done once in a few years; machines are available on rent at custom hiring centres.' },
  hi: { t: 'लेज़र से खेत समतल करना', s: 'खेत को बिल्कुल समतल बनाना', how: 'लेज़र से चलने वाली ट्रैक्टर की मशीन खेत की सतह को लगभग पूरी तरह समतल कर देती है। इससे पानी हर जगह बराबर फैलता है, सिंचाई में कम पानी और कम समय लगता है, फसल एक समान बढ़ती है और खाद का बेहतर उपयोग होता है। यह आमतौर पर कुछ सालों में एक बार किया जाता है; मशीनें कस्टम हायरिंग केंद्रों पर किराये पर मिलती हैं।' },
  mr: { t: 'लेझरने जमीन सपाटीकरण', s: 'शेत अगदी सपाट करणे', how: 'लेझरच्या मार्गदर्शनाने चालणारे ट्रॅक्टरचे यंत्र शेताचा पृष्ठभाग जवळजवळ पूर्ण सपाट करते. त्यामुळे पाणी सगळीकडे सारखे पसरते, सिंचनाला कमी पाणी आणि वेळ लागतो, पीक एकसारखे वाढते आणि खताचा चांगला वापर होतो. हे साधारणपणे काही वर्षांतून एकदा केले जाते; यंत्रे अवजारे बँकेत भाड्याने मिळतात.' },
  te: { t: 'లేజర్‌తో భూమి చదును', s: 'పొలాన్ని పూర్తిగా సమతలం చేయడం', how: 'లేజర్ మార్గదర్శనంతో నడిచే ట్రాక్టర్ యంత్రం పొలం ఉపరితలాన్ని దాదాపు పూర్తిగా సమతలం చేస్తుంది. దాంతో నీరు అంతటా సమానంగా పారుతుంది, సాగుకు తక్కువ నీరు, తక్కువ సమయం పడుతుంది, పంట సమానంగా పెరుగుతుంది, ఎరువు బాగా ఉపయోగపడుతుంది. సాధారణంగా కొన్నేళ్లకు ఒకసారి చేస్తారు; యంత్రాలు కస్టమ్ హైరింగ్ కేంద్రాల్లో అద్దెకు దొరుకుతాయి.' },
  ta: { t: 'லேசர் நிலச் சமன்', s: 'வயலை முழுமையாகச் சமமாக்குதல்', how: 'லேசர் வழிகாட்டலில் இயங்கும் டிராக்டர் கருவி வயலின் மேற்பரப்பைக் கிட்டத்தட்ட முழுமையாகச் சமமாக்கும். இதனால் நீர் எல்லா இடத்திலும் சமமாகப் பரவும்; பாசனத்துக்குக் குறைந்த நீரும் நேரமும் போதும்; பயிர் சீராக வளரும்; உரம் நன்கு பயன்படும். பொதுவாகச் சில ஆண்டுகளுக்கு ஒருமுறை செய்யப்படுகிறது; இயந்திரங்கள் வாடகை மையங்களில் கிடைக்கும்.' } },

/* ======================= Modern methods & extra income ======================= */
{ id: 'polyhouse', cat: 'modern', icon: '🏠',
  k: ['polyhouse', 'greenhouse', 'green house', 'shade net', 'protected cultivation', 'पॉलीहाउस', 'पोलीहाउस', 'ग्रीनहाउस', 'शेड नेट', 'शेडनेट', 'पॉलिहाऊस', 'పాలీహౌస్', 'షేడ్ నెట్', 'గ్రీన్‌హౌస్', 'பசுமைக்குடில்', 'நிழல் வலை', 'பாலிஹவுஸ்'],
  en: { t: 'Polyhouse and shade net', s: 'Grow high-value crops under cover', how: 'Crops like capsicum, cucumber, tomato and flowers are grown under a plastic-covered structure (polyhouse) or in a shade net house. The cover protects from heavy rain, hail, strong sun and many insects, so crops can be grown off-season and quality and yield per square metre go up. Setup cost is high, so start small and get training first; subsidy is available under the horticulture mission (MIDH).' },
  hi: { t: 'पॉलीहाउस और शेड नेट', s: 'ढके ढाँचे में ऊँचे दाम वाली फसलें', how: 'शिमला मिर्च, खीरा, टमाटर और फूल जैसी फसलें प्लास्टिक से ढके ढाँचे (पॉलीहाउस) या शेड नेट हाउस में उगाई जाती हैं। ढकाव भारी बारिश, ओले, तेज़ धूप और कई कीटों से बचाता है, इसलिए बेमौसम फसल ली जा सकती है और प्रति वर्ग मीटर गुणवत्ता व उपज बढ़ती है। लागत ज़्यादा है, इसलिए छोटे से शुरू करें और पहले प्रशिक्षण लें; बागवानी मिशन (MIDH) में सब्सिडी मिलती है।' },
  mr: { t: 'पॉलिहाऊस आणि शेडनेट', s: 'झाकलेल्या रचनेत जास्त किमतीची पिके', how: 'ढोबळी मिरची, काकडी, टोमॅटो आणि फुले अशी पिके प्लास्टिकने झाकलेल्या रचनेत (पॉलिहाऊस) किंवा शेडनेट गृहात घेतली जातात. आच्छादन मुसळधार पाऊस, गारा, कडक ऊन आणि अनेक किडींपासून वाचवते, त्यामुळे बिगरहंगामी पीक घेता येते आणि प्रति चौरस मीटर दर्जा व उत्पादन वाढते. खर्च जास्त आहे, म्हणून लहान सुरुवात करा आणि आधी प्रशिक्षण घ्या; फलोत्पादन अभियानात (MIDH) अनुदान मिळते.' },
  te: { t: 'పాలీహౌస్, షేడ్ నెట్', s: 'కప్పు కింద అధిక విలువ పంటలు', how: 'క్యాప్సికం, దోస, టమాటా, పూలు వంటి పంటలను ప్లాస్టిక్ కప్పిన నిర్మాణం (పాలీహౌస్) లేదా షేడ్ నెట్ హౌస్‌లో పండిస్తారు. కప్పు భారీ వర్షం, వడగళ్లు, తీవ్రమైన ఎండ, చాలా పురుగుల నుంచి కాపాడుతుంది, అందుకే అకాల పంటలు వేయవచ్చు, చదరపు మీటరుకు నాణ్యత, దిగుబడి పెరుగుతాయి. ఖర్చు ఎక్కువ, కాబట్టి చిన్నగా మొదలుపెట్టి ముందు శిక్షణ తీసుకోండి; ఉద్యాన మిషన్ (MIDH) కింద సబ్సిడీ ఉంది.' },
  ta: { t: 'பசுமைக்குடில், நிழல் வலை', s: 'மூடிய அமைப்பில் அதிக மதிப்புப் பயிர்கள்', how: 'குடைமிளகாய், வெள்ளரி, தக்காளி, பூக்கள் போன்ற பயிர்களைப் பிளாஸ்டிக் மூடிய அமைப்பு (பசுமைக்குடில்) அல்லது நிழல் வலைக் கூடத்தில் வளர்க்கிறார்கள். மூடுதல் கனமழை, ஆலங்கட்டி, கடும் வெயில், பல பூச்சிகளிலிருந்து காக்கும்; அதனால் பருவமில்லாக் காலத்திலும் பயிரிடலாம், சதுர மீட்டருக்குத் தரமும் மகசூலும் கூடும். செலவு அதிகம்; எனவே சிறிய அளவில் தொடங்கி முதலில் பயிற்சி பெறுங்கள்; தோட்டக்கலை இயக்கத்தில் (MIDH) மானியம் உண்டு.' } },

{ id: 'lowtunnel', cat: 'modern', icon: '⛺',
  k: ['low tunnel', 'low tunnels', 'tunnel', 'लो टनल', 'टनल', 'सुरंग', 'लो टनेल', 'बोगदे', 'టన్నెల్', 'లో టన్నెల్', 'సొరంగం', 'சுரங்கக் குடில்', 'சுரங்கம்'],
  en: { t: 'Low tunnels', s: 'Small plastic tunnels for early crops', how: 'Thin plastic sheet is stretched over bent wires or bamboo above vegetable rows, forming low tunnels. In winter they keep plants warm, so cucurbits like bottle gourd, cucumber and muskmelon can be sown early and reach the market when prices are higher. The plastic is removed once the weather warms up.' },
  hi: { t: 'लो टनल', s: 'अगेती फसल के लिए छोटी प्लास्टिक सुरंग', how: 'सब्ज़ी की कतारों के ऊपर मुड़े तारों या बाँस पर पतली प्लास्टिक शीट तानकर छोटी सुरंगें बनाई जाती हैं। सर्दी में ये पौधों को गर्म रखती हैं, इसलिए लौकी, खीरा, खरबूजा जैसी बेल वाली फसलें जल्दी बोई जा सकती हैं और ऊँचे दाम के समय बाज़ार पहुँचती हैं। मौसम गर्म होने पर प्लास्टिक हटा दिया जाता है।' },
  mr: { t: 'लो टनेल', s: 'लवकर पिकांसाठी लहान प्लास्टिक बोगदे', how: 'भाज्यांच्या ओळींवर वाकवलेल्या तारा किंवा बांबूवर पातळ प्लास्टिक ताणून लहान बोगदे केले जातात. हिवाळ्यात ते रोपांना उबदार ठेवतात, त्यामुळे दुधी भोपळा, काकडी, खरबूज यांसारखी वेलवर्गीय पिके लवकर लावता येतात आणि जास्त भाव असताना बाजारात पोहोचतात. हवामान उबदार झाल्यावर प्लास्टिक काढले जाते.' },
  te: { t: 'లో టన్నెల్స్', s: 'ముందస్తు పంటలకు చిన్న ప్లాస్టిక్ సొరంగాలు', how: 'కూరగాయ వరుసలపై వంచిన తీగలు లేదా వెదురుపై పలుచని ప్లాస్టిక్ షీట్ లాగి చిన్న సొరంగాలు చేస్తారు. చలికాలంలో ఇవి మొక్కలను వెచ్చగా ఉంచుతాయి, అందుకే సొర, దోస, కర్బూజ వంటి తీగ పంటలను ముందుగానే వేసి, ధరలు ఎక్కువగా ఉన్నప్పుడు మార్కెట్‌కు తేవచ్చు. వాతావరణం వేడెక్కాక ప్లాస్టిక్ తీసేస్తారు.' },
  ta: { t: 'தாழ் சுரங்கக் குடில்', s: 'முன்பருவப் பயிருக்குச் சிறிய பிளாஸ்டிக் சுரங்கம்', how: 'காய்கறி வரிசைகளின் மேல் வளைத்த கம்பிகள் அல்லது மூங்கிலில் மெல்லிய பிளாஸ்டிக் தாளை இழுத்துக் கட்டி தாழ்வான சுரங்கங்கள் அமைக்கிறார்கள். குளிர்காலத்தில் இவை செடிகளை வெதுவெதுப்பாக வைக்கும்; அதனால் சுரை, வெள்ளரி, முலாம்பழம் போன்ற கொடிப் பயிர்களை முன்கூட்டியே விதைத்து, விலை அதிகமாக இருக்கும் போது சந்தைக்குக் கொண்டுவரலாம். வானிலை வெப்பமானதும் பிளாஸ்டிக் அகற்றப்படும்.' } },

{ id: 'trellis', cat: 'modern', icon: '🎋',
  k: ['trellis', 'machan', 'pandal', 'staking', 'creeper', 'creepers', 'मचान', 'ट्रेलिस', 'बेल', 'बेलें', 'मांडव', 'वेली', 'పందిరి', 'తీగ', 'తీగలు', 'பந்தல்', 'கொடி'],
  en: { t: 'Trellis farming (machan)', s: 'Let creepers climb on a frame', how: 'Creepers like bottle gourd, bitter gourd, ridge gourd and cucumber are trained onto a frame of bamboo poles and wires (machan or pandal), and tomato is tied to stakes. Fruits hang in the air, stay clean and straight, rot less, and are easier to pick and spray, so more of the harvest can be sold. The land under the frame can grow a short crop like leafy vegetables.' },
  hi: { t: 'मचान (ट्रेलिस) खेती', s: 'बेलों को ढाँचे पर चढ़ाना', how: 'लौकी, करेला, तोरई और खीरे जैसी बेलों को बाँस के खंभों और तारों के ढाँचे (मचान) पर चढ़ाया जाता है, और टमाटर को डंडियों से बाँधा जाता है। फल हवा में लटकते हैं, साफ़ और सीधे रहते हैं, कम सड़ते हैं, और तोड़ना व छिड़काव आसान होता है, इसलिए ज़्यादा उपज बिकने लायक होती है। मचान के नीचे की ज़मीन में पत्तेदार सब्ज़ी जैसी छोटी फसल ली जा सकती है।' },
  mr: { t: 'मांडव (ट्रेलिस) शेती', s: 'वेलींना मांडवावर चढवणे', how: 'दुधी भोपळा, कारले, दोडका आणि काकडीसारख्या वेली बांबू आणि तारांच्या मांडवावर चढवल्या जातात, आणि टोमॅटो काठ्यांना बांधला जातो. फळे हवेत लटकतात, स्वच्छ आणि सरळ राहतात, कमी सडतात, आणि तोडणी व फवारणी सोपी होते, त्यामुळे जास्त माल विक्रीयोग्य होतो. मांडवाखालच्या जमिनीत पालेभाज्यांसारखे लहान पीक घेता येते.' },
  te: { t: 'పందిరి సాగు (ట్రెల్లిస్)', s: 'తీగలను చట్రంపైకి ఎక్కించడం', how: 'సొర, కాకర, బీర, దోస వంటి తీగలను వెదురు కర్రలు, తీగల చట్రం (పందిరి) పైకి పాకిస్తారు, టమాటాను కర్రలకు కడతారు. కాయలు గాలిలో వేలాడుతూ శుభ్రంగా, నిటారుగా ఉంటాయి, తక్కువ కుళ్తాయి, కోయడం, పిచికారీ సులభం, అందుకే ఎక్కువ దిగుబడి అమ్మకానికి పనికొస్తుంది. పందిరి కింది నేలలో ఆకుకూరల వంటి చిన్న పంట వేయవచ్చు.' },
  ta: { t: 'பந்தல் சாகுபடி', s: 'கொடிகளைப் பந்தலில் ஏற்றுதல்', how: 'சுரை, பாகல், பீர்க்கை, வெள்ளரி போன்ற கொடிகளை மூங்கில் கம்பங்களும் கம்பிகளும் கொண்ட பந்தலில் ஏற்றுகிறார்கள்; தக்காளியைக் குச்சிகளில் கட்டுகிறார்கள். காய்கள் காற்றில் தொங்கி, சுத்தமாகவும் நேராகவும் இருக்கும்; குறைவாக அழுகும்; பறிப்பதும் தெளிப்பதும் எளிது; அதனால் அதிக மகசூல் விற்பனைக்கு ஏற்றதாகும். பந்தலுக்குக் கீழுள்ள நிலத்தில் கீரை போன்ற குறுகிய பயிரை வளர்க்கலாம்.' } },

{ id: 'hydroponics', cat: 'modern', icon: '🫧',
  k: ['hydroponics', 'hydroponic', 'without soil', 'हाइड्रोपोनिक्स', 'हाइड्रोपोनिक', 'बिना मिट्टी', 'मातीशिवाय', 'हायड्रोपोनिक्स', 'హైడ్రోపోనిక్స్', 'మట్టి లేకుండా', 'ஹைட்ரோபோனிக்ஸ்', 'மண்ணில்லா'],
  en: { t: 'Hydroponics', s: 'Grow plants without soil, in nutrient water', how: 'Plants grow with their roots in water that carries all the nutrients they need, held in pipes or trays, often under a shade net or indoors. It uses much less water than soil farming and suits leafy greens, herbs and some vegetables in small spaces or near cities. The setup and nutrient solution cost money and it needs regular checking, so learn it on a small scale first.' },
  hi: { t: 'हाइड्रोपोनिक्स', s: 'बिना मिट्टी, पोषक पानी में खेती', how: 'पौधों की जड़ें ऐसे पानी में रहती हैं जिसमें सभी ज़रूरी पोषक तत्व घुले होते हैं; पौधे पाइपों या ट्रे में, अक्सर शेड नेट या घर के अंदर लगाए जाते हैं। इसमें मिट्टी वाली खेती से बहुत कम पानी लगता है और यह छोटी जगह या शहरों के पास पत्तेदार सब्ज़ियों, जड़ी-बूटियों और कुछ सब्ज़ियों के लिए ठीक है। ढाँचे और पोषक घोल पर खर्च होता है और नियमित जाँच चाहिए, इसलिए पहले छोटे स्तर पर सीखें।' },
  mr: { t: 'हायड्रोपोनिक्स', s: 'मातीशिवाय, पोषक पाण्यात शेती', how: 'झाडांची मुळे अशा पाण्यात असतात ज्यात सर्व आवश्यक अन्नद्रव्ये विरघळलेली असतात; झाडे नळ्यांमध्ये किंवा ट्रेमध्ये, अनेकदा शेडनेटमध्ये किंवा घरात लावली जातात. यात मातीतील शेतीपेक्षा खूप कमी पाणी लागते आणि लहान जागेत किंवा शहरांजवळ पालेभाज्या, औषधी वनस्पती आणि काही भाज्यांसाठी हे योग्य आहे. रचना आणि पोषक द्रावणावर खर्च येतो आणि नियमित तपासणी लागते, म्हणून आधी लहान प्रमाणात शिका.' },
  te: { t: 'హైడ్రోపోనిక్స్', s: 'మట్టి లేకుండా, పోషక నీటిలో సాగు', how: 'మొక్కల వేర్లు అవసరమైన అన్ని పోషకాలు కరిగిన నీటిలో ఉంటాయి; మొక్కలను పైపులు లేదా ట్రేలలో, తరచూ షేడ్ నెట్ కింద లేదా ఇంట్లో పెంచుతారు. దీనికి మట్టి సాగు కంటే చాలా తక్కువ నీరు చాలు, చిన్న స్థలాల్లో లేదా నగరాల దగ్గర ఆకుకూరలు, మూలికలు, కొన్ని కూరగాయలకు ఇది సరిపోతుంది. నిర్మాణానికి, పోషక ద్రావణానికి ఖర్చు అవుతుంది, క్రమం తప్పకుండా పరిశీలన అవసరం, కాబట్టి ముందు చిన్న స్థాయిలో నేర్చుకోండి.' },
  ta: { t: 'மண்ணில்லா வேளாண்மை (ஹைட்ரோபோனிக்ஸ்)', s: 'மண் இல்லாமல் சத்து நீரில் சாகுபடி', how: 'செடிகளின் வேர்கள் தேவையான எல்லாச் சத்துக்களும் கரைந்த நீரில் இருக்கும்; செடிகளைக் குழாய்கள் அல்லது தட்டுகளில், பெரும்பாலும் நிழல் வலைக்குள் அல்லது வீட்டுக்குள் வளர்க்கிறார்கள். இதற்கு மண் சாகுபடியை விட மிகக் குறைவான நீர் போதும்; சிறிய இடங்களில் அல்லது நகரங்களுக்கு அருகில் கீரைகள், மூலிகைகள், சில காய்கறிகளுக்கு ஏற்றது. அமைப்புக்கும் சத்துக் கரைசலுக்கும் செலவாகும், தொடர்ந்து கண்காணிக்க வேண்டும்; எனவே முதலில் சிறிய அளவில் கற்றுக்கொள்ளுங்கள்.' } },

{ id: 'hdp', cat: 'modern', icon: '🥭',
  k: ['high density', 'high density planting', 'hdp', 'pruning', 'orchard', 'सघन बागवानी', 'सघन', 'हाई डेंसिटी', 'कटाई छँटाई', 'छँटाई', 'बाग', 'बागवानी', 'घन लागवड', 'छाटणी', 'फळबाग', 'సాంద్ర', 'కత్తిరింపు', 'తోట', 'அடர் நடவு', 'கவாத்து', 'தோட்டம்'],
  en: { t: 'High density orchards', s: 'More fruit trees per acre, kept small by pruning', how: 'Fruit trees like mango, guava and apple are planted much closer than usual and kept small and open by regular pruning and training. More trees per acre start bearing earlier and give more fruit per acre, and small trees are easier to spray and harvest. It needs good varieties, drip irrigation and timely pruning; learn the method for your fruit at a horticulture centre.' },
  hi: { t: 'सघन बागवानी (हाई डेंसिटी)', s: 'प्रति एकड़ ज़्यादा फल पेड़, कटाई से छोटे रखें', how: 'आम, अमरूद और सेब जैसे फल पेड़ सामान्य से काफ़ी पास-पास लगाए जाते हैं और नियमित कटाई-छँटाई से छोटे व खुले रखे जाते हैं। प्रति एकड़ ज़्यादा पेड़ जल्दी फल देने लगते हैं और प्रति एकड़ ज़्यादा फल मिलता है, और छोटे पेड़ों पर छिड़काव व तुड़ाई आसान होती है। इसके लिए अच्छी किस्में, ड्रिप सिंचाई और समय पर कटाई-छँटाई चाहिए; अपने फल के लिए तरीका बागवानी केंद्र से सीखें।' },
  mr: { t: 'घन लागवड (हाय डेन्सिटी)', s: 'एकरी जास्त फळझाडे, छाटणीने लहान ठेवणे', how: 'आंबा, पेरू आणि सफरचंदासारखी फळझाडे नेहमीपेक्षा खूप जवळ लावली जातात आणि नियमित छाटणी व वळण देऊन लहान व मोकळी ठेवली जातात. एकरी जास्त झाडे लवकर फळावर येतात आणि एकरी जास्त फळे मिळतात, आणि लहान झाडांवर फवारणी व तोडणी सोपी होते. यासाठी चांगल्या जाती, ठिबक सिंचन आणि वेळेवर छाटणी लागते; आपल्या फळासाठी पद्धत फलोत्पादन केंद्रात शिका.' },
  te: { t: 'సాంద్ర తోటలు (హై డెన్సిటీ)', s: 'ఎకరానికి ఎక్కువ పండ్ల చెట్లు, కత్తిరింపుతో చిన్నగా', how: 'మామిడి, జామ, ఆపిల్ వంటి పండ్ల చెట్లను సాధారణం కంటే చాలా దగ్గరగా నాటి, క్రమం తప్పని కత్తిరింపు, శిక్షణతో చిన్నగా, విశాలంగా ఉంచుతారు. ఎకరానికి ఎక్కువ చెట్లు త్వరగా కాపుకు వచ్చి ఎకరానికి ఎక్కువ పండ్లు ఇస్తాయి, చిన్న చెట్లపై పిచికారీ, కోత సులభం. దీనికి మంచి రకాలు, బిందు సేద్యం, సకాలంలో కత్తిరింపు అవసరం; మీ పండుకు పద్ధతిని ఉద్యాన కేంద్రంలో నేర్చుకోండి.' },
  ta: { t: 'அடர் நடவுத் தோட்டம்', s: 'ஏக்கருக்கு அதிக மரங்கள், கவாத்தால் சிறியதாக', how: 'மா, கொய்யா, ஆப்பிள் போன்ற பழ மரங்களை வழக்கத்தை விட மிக நெருக்கமாக நட்டு, தொடர்ந்து கவாத்து செய்து சிறியதாகவும் திறந்ததாகவும் வைக்கிறார்கள். ஏக்கருக்கு அதிக மரங்கள் விரைவில் காய்க்கத் தொடங்கி ஏக்கருக்கு அதிகப் பழம் தரும்; சிறிய மரங்களில் தெளிப்பதும் பறிப்பதும் எளிது. இதற்கு நல்ல ரகங்கள், சொட்டு நீர்ப்பாசனம், சரியான நேரக் கவாத்து தேவை; உங்கள் பழத்துக்கான முறையைத் தோட்டக்கலை மையத்தில் கற்றுக்கொள்ளுங்கள்.' } },

{ id: 'bees', cat: 'modern', icon: '🐝',
  k: ['bee', 'bees', 'beekeeping', 'honey', 'pollination', 'मधुमक्खी', 'मधुमक्खी पालन', 'शहद', 'परागण', 'मधमाशी', 'मधमाशी पालन', 'मध', 'परागीभवन', 'తేనెటీగ', 'తేనెటీగలు', 'తేనె', 'పరాగసంపర్కం', 'தேனீ', 'தேனீ வளர்ப்பு', 'தேன்', 'மகரந்தச் சேர்க்கை'],
  en: { t: 'Beekeeping for pollination', s: 'Bees raise fruit and seed set, and give honey', how: 'Bee boxes kept near crops like mustard, sunflower, litchi, apple and many vegetables help flowers get pollinated, so more fruits and seeds form. Honey and wax give extra income. Avoid spraying insecticide while flowers are open, or spray in the evening after bees return; training and help are available under the National Beekeeping and Honey Mission.' },
  hi: { t: 'परागण के लिए मधुमक्खी पालन', s: 'मधुमक्खी से ज़्यादा फल-दाना और शहद', how: 'सरसों, सूरजमुखी, लीची, सेब और कई सब्ज़ियों के पास रखे मधुमक्खी के बक्से फूलों के परागण में मदद करते हैं, जिससे ज़्यादा फल और दाने बनते हैं। शहद और मोम से अतिरिक्त कमाई होती है। फूल खिले हों तब कीटनाशक का छिड़काव न करें, या शाम को मधुमक्खियों के लौटने के बाद करें; राष्ट्रीय मधुमक्खी पालन और शहद मिशन में प्रशिक्षण और मदद मिलती है।' },
  mr: { t: 'परागीभवनासाठी मधमाशी पालन', s: 'मधमाश्यांमुळे जास्त फळ-दाणे आणि मध', how: 'मोहरी, सूर्यफूल, लिची, सफरचंद आणि अनेक भाज्यांजवळ ठेवलेल्या मधमाश्यांच्या पेट्या फुलांच्या परागीभवनाला मदत करतात, त्यामुळे जास्त फळे आणि दाणे तयार होतात. मध आणि मेणापासून जादा उत्पन्न मिळते. फुले उमललेली असताना कीटकनाशक फवारू नका, किंवा संध्याकाळी मधमाश्या परतल्यानंतर फवारा; राष्ट्रीय मधमाशी पालन व मध अभियानात प्रशिक्षण आणि मदत मिळते.' },
  te: { t: 'పరాగసంపర్కానికి తేనెటీగల పెంపకం', s: 'తేనెటీగలతో ఎక్కువ కాయ, గింజ, తేనె', how: 'ఆవాలు, పొద్దుతిరుగుడు, లిచీ, ఆపిల్, చాలా కూరగాయల దగ్గర ఉంచిన తేనెటీగల పెట్టెలు పూల పరాగసంపర్కానికి సహాయపడతాయి, దాంతో ఎక్కువ కాయలు, గింజలు ఏర్పడతాయి. తేనె, మైనం ద్వారా అదనపు ఆదాయం వస్తుంది. పూలు విచ్చుకున్నప్పుడు పురుగుమందు పిచికారీ చేయకండి, లేదా సాయంత్రం తేనెటీగలు తిరిగి వచ్చాక చేయండి; జాతీయ తేనెటీగల పెంపకం, తేనె మిషన్ కింద శిక్షణ, సహాయం లభిస్తాయి.' },
  ta: { t: 'மகரந்தச் சேர்க்கைக்குத் தேனீ வளர்ப்பு', s: 'தேனீக்களால் அதிகக் காய், விதை, தேன்', how: 'கடுகு, சூரியகாந்தி, லிச்சி, ஆப்பிள், பல காய்கறிகளுக்கு அருகில் வைக்கும் தேனீப் பெட்டிகள் பூக்களின் மகரந்தச் சேர்க்கைக்கு உதவுகின்றன; இதனால் அதிகக் காய்களும் விதைகளும் உருவாகும். தேனும் மெழுகும் கூடுதல் வருமானம் தரும். பூக்கள் மலர்ந்திருக்கும் போது பூச்சிக்கொல்லி தெளிக்காதீர்கள், அல்லது மாலையில் தேனீக்கள் திரும்பிய பிறகு தெளியுங்கள்; தேசியத் தேனீ வளர்ப்பு மற்றும் தேன் இயக்கத்தின் கீழ் பயிற்சியும் உதவியும் கிடைக்கும்.' } },

{ id: 'mushroom', cat: 'modern', icon: '🍄',
  k: ['mushroom', 'mushrooms', 'spawn', 'oyster', 'मशरूम', 'ढींगरी', 'खुंभी', 'अळिंबी', 'धिंगरी', 'పుట్టగొడుగు', 'పుట్టగొడుగులు', 'మష్రూమ్', 'காளான்', 'காளான் வளர்ப்பு'],
  en: { t: 'Mushroom growing', s: 'Extra income from straw in a closed room', how: 'Oyster mushroom grows on chopped and cleaned paddy or wheat straw filled into plastic bags with spawn (mushroom seed) and kept in a dark, damp room; button mushroom needs compost and cooler conditions. Mushrooms are ready within weeks, need very little land, and turn crop waste into income; the used straw becomes manure. Buy spawn from a reliable lab and take short training at a Krishi Vigyan Kendra.' },
  hi: { t: 'मशरूम उत्पादन', s: 'बंद कमरे में पुआल से अतिरिक्त कमाई', how: 'ढींगरी (ऑयस्टर) मशरूम कटे और साफ़ किए धान या गेहूँ के भूसे पर उगता है, जिसे स्पॉन (मशरूम के बीज) के साथ प्लास्टिक थैलों में भरकर अँधेरे, नम कमरे में रखा जाता है; बटन मशरूम के लिए कम्पोस्ट और ठंडा मौसम चाहिए। मशरूम कुछ ही हफ़्तों में तैयार होते हैं, बहुत कम ज़मीन लगती है, और फसल का कचरा कमाई बन जाता है; बचा भूसा खाद बन जाता है। स्पॉन भरोसेमंद लैब से खरीदें और कृषि विज्ञान केंद्र से छोटा प्रशिक्षण लें।' },
  mr: { t: 'अळिंबी (मशरूम) उत्पादन', s: 'बंद खोलीत काडापासून जादा उत्पन्न', how: 'धिंगरी (ऑयस्टर) अळिंबी कापलेल्या आणि स्वच्छ केलेल्या भात किंवा गव्हाच्या काडावर उगवते, जे स्पॉन (अळिंबीचे बी) सोबत प्लास्टिक पिशव्यांत भरून अंधाऱ्या, दमट खोलीत ठेवले जाते; बटन अळिंबीला कंपोस्ट आणि थंड हवामान लागते. अळिंबी काही आठवड्यांत तयार होते, खूप कमी जागा लागते, आणि पिकांचा कचरा उत्पन्नात बदलतो; वापरलेले काड खत बनते. स्पॉन विश्वासार्ह प्रयोगशाळेतून घ्या आणि कृषी विज्ञान केंद्रात लहान प्रशिक्षण घ्या.' },
  te: { t: 'పుట్టగొడుగుల పెంపకం', s: 'మూసి గదిలో గడ్డితో అదనపు ఆదాయం', how: 'ఆయిస్టర్ (ముత్యపు చిప్ప) పుట్టగొడుగులు కత్తిరించి శుభ్రం చేసిన వరి లేదా గోధుమ గడ్డిపై పెరుగుతాయి, దాన్ని స్పాన్ (పుట్టగొడుగు విత్తనం) తో ప్లాస్టిక్ సంచుల్లో నింపి చీకటి, తేమ గదిలో ఉంచుతారు; బటన్ పుట్టగొడుగులకు కంపోస్ట్, చల్లని వాతావరణం అవసరం. కొన్ని వారాల్లోనే పుట్టగొడుగులు తయారవుతాయి, చాలా తక్కువ స్థలం సరిపోతుంది, పంట వ్యర్థం ఆదాయంగా మారుతుంది; వాడిన గడ్డి ఎరువు అవుతుంది. స్పాన్‌ను నమ్మకమైన ల్యాబ్ నుంచి కొని, కృషి విజ్ఞాన కేంద్రంలో చిన్న శిక్షణ తీసుకోండి.' },
  ta: { t: 'காளான் வளர்ப்பு', s: 'மூடிய அறையில் வைக்கோலால் கூடுதல் வருமானம்', how: 'சிப்பிக் காளான் நறுக்கிச் சுத்தம் செய்த நெல் அல்லது கோதுமை வைக்கோலில் வளரும்; அதை வித்துடன் (காளான் விதை) பிளாஸ்டிக் பைகளில் நிரப்பி இருட்டான, ஈரமான அறையில் வைக்கிறார்கள்; மொட்டுக் காளானுக்கு மட்கிய உரமும் குளிர்ந்த சூழலும் தேவை. சில வாரங்களிலேயே காளான் தயாராகும், மிகக் குறைந்த இடம் போதும், பயிர்க் கழிவு வருமானமாக மாறும்; பயன்படுத்திய வைக்கோல் உரமாகும். வித்தை நம்பகமான ஆய்வகத்தில் வாங்கி, வேளாண் அறிவியல் நிலையத்தில் சிறிய பயிற்சி பெறுங்கள்.' } },

{ id: 'ipm', cat: 'modern', icon: '🐞',
  k: ['ipm', 'integrated pest management', 'pest', 'pests', 'trichogramma', 'pheromone', 'trap', 'कीट', 'कीड़े', 'कीट प्रबंधन', 'आईपीएम', 'ट्राइकोग्रामा', 'फेरोमोन', 'ट्रैप', 'कीड', 'कीड व्यवस्थापन', 'సస్యరక్షణ', 'పురుగు', 'పురుగులు', 'பூச்சி', 'பூச்சி மேலாண்மை', 'ஐபிஎம்'],
  en: { t: 'Integrated pest management (IPM)', s: 'Control pests with less poison', how: 'Check the field regularly and act only when pests cross a damaging level. Use resistant varieties, clean cultivation, yellow sticky and pheromone traps, neem-based sprays and helpful bio-agents such as Trichogramma egg cards and Trichoderma; use chemical pesticide only as the last step, at the right dose. Costs come down, natural enemies of pests survive, and produce has fewer residues.' },
  hi: { t: 'एकीकृत कीट प्रबंधन (IPM)', s: 'कम ज़हर में कीटों पर काबू', how: 'खेत की नियमित निगरानी करें और कीट नुकसान के स्तर से ऊपर जाएँ तभी कदम उठाएँ। रोगरोधी किस्में, साफ़-सुथरी खेती, पीले चिपचिपे और फेरोमोन ट्रैप, नीम आधारित छिड़काव और ट्राइकोग्रामा कार्ड व ट्राइकोडर्मा जैसे लाभदायक जैविक एजेंट अपनाएँ; रासायनिक दवा सबसे आख़िरी उपाय के रूप में, सही मात्रा में ही डालें। खर्च घटता है, कीटों के प्राकृतिक दुश्मन बचे रहते हैं, और उपज में दवा के अवशेष कम होते हैं।' },
  mr: { t: 'एकात्मिक कीड व्यवस्थापन (IPM)', s: 'कमी विषात किडींवर नियंत्रण', how: 'शेताची नियमित पाहणी करा आणि कीड नुकसानीच्या पातळीपेक्षा वाढली तरच उपाय करा. प्रतिकारक जाती, स्वच्छ मशागत, पिवळे चिकट आणि कामगंध सापळे, कडुनिंबावर आधारित फवारणी आणि ट्रायकोग्रामा कार्ड व ट्रायकोडर्मासारखे उपयुक्त जैविक घटक वापरा; रासायनिक औषध सर्वात शेवटचा उपाय म्हणून, योग्य मात्रेतच वापरा. खर्च कमी होतो, किडींचे नैसर्गिक शत्रू टिकतात, आणि मालात औषधांचे अंश कमी राहतात.' },
  te: { t: 'సమగ్ర సస్యరక్షణ (IPM)', s: 'తక్కువ విషంతో పురుగుల అదుపు', how: 'పొలాన్ని క్రమం తప్పకుండా పరిశీలించి, పురుగులు నష్ట స్థాయి దాటినప్పుడే చర్యలు తీసుకోండి. నిరోధక రకాలు, శుభ్రమైన సాగు, పసుపు జిగురు అట్టలు, లింగాకర్షక బుట్టలు, వేప ఆధారిత పిచికారీలు, ట్రైకోగ్రామా కార్డులు, ట్రైకోడెర్మా వంటి మేలు చేసే జీవ నియంత్రకాలు వాడండి; రసాయన పురుగుమందును చివరి అస్త్రంగా, సరైన మోతాదులోనే వాడండి. ఖర్చు తగ్గుతుంది, పురుగుల సహజ శత్రువులు బతుకుతాయి, పంటలో మందు అవశేషాలు తగ్గుతాయి.' },
  ta: { t: 'ஒருங்கிணைந்த பூச்சி மேலாண்மை (IPM)', s: 'குறைந்த நச்சில் பூச்சிக் கட்டுப்பாடு', how: 'வயலைத் தொடர்ந்து கண்காணித்து, பூச்சிகள் சேத அளவைத் தாண்டும் போது மட்டுமே நடவடிக்கை எடுங்கள். எதிர்ப்புத் திறன் ரகங்கள், சுத்தமான சாகுபடி, மஞ்சள் ஒட்டுப் பொறி, இனக்கவர்ச்சிப் பொறி, வேம்பு சார்ந்த தெளிப்புகள், டிரைக்கோகிரம்மா அட்டை, டிரைக்கோடெர்மா போன்ற நன்மை உயிரிகளைப் பயன்படுத்துங்கள்; ரசாயனப் பூச்சிக்கொல்லியைக் கடைசி வழியாக, சரியான அளவில் மட்டுமே பயன்படுத்துங்கள். செலவு குறையும், பூச்சிகளின் இயற்கை எதிரிகள் தப்பும், விளைபொருளில் மருந்து எச்சம் குறையும்.' } },

{ id: 'ratoon', cat: 'modern', icon: '🎍',
  k: ['ratoon', 'ratooning', 'पेड़ी', 'रैटून', 'पेड़ी फसल', 'खोडवा', 'కార్శి', 'రటూన్', 'மறுதாம்பு', 'கட்டைப் பயிர்'],
  en: { t: 'Ratoon cropping', s: 'A second harvest from the same roots', how: 'After harvest, crops like sugarcane and banana regrow from the stubble or the base and give another crop without new planting. Planting cost and time are saved; cut the old stubble evenly close to the ground, fill gaps, and give manure, fertilizer and irrigation on time so the ratoon yields well. Keep ratooning only while the crop stays healthy.' },
  hi: { t: 'पेड़ी (रैटून) फसल', s: 'उन्हीं जड़ों से दूसरी कटाई', how: 'कटाई के बाद गन्ना और केला जैसी फसलें ठूँठ या जड़ से फिर उग आती हैं और बिना नई बुवाई के एक और फसल देती हैं। बुवाई का खर्च और समय बचता है; पुराने ठूँठ ज़मीन के पास बराबर काटें, खाली जगह भरें, और समय पर खाद, उर्वरक और सिंचाई दें ताकि पेड़ी अच्छी उपज दे। पेड़ी तभी तक लें जब तक फसल स्वस्थ रहे।' },
  mr: { t: 'खोडवा (रॅटून) पीक', s: 'त्याच मुळांपासून दुसरे उत्पादन', how: 'काढणीनंतर ऊस आणि केळीसारखी पिके बुडख्यापासून पुन्हा फुटतात आणि नवी लागवड न करता आणखी एक पीक देतात. लागवडीचा खर्च आणि वेळ वाचतो; जुने बुडखे जमिनीलगत सारखे कापा, नांग्या भरा, आणि वेळेवर खत आणि पाणी द्या म्हणजे खोडवा चांगले उत्पादन देईल. पीक निरोगी असेपर्यंतच खोडवा घ्या.' },
  te: { t: 'కార్శి (రటూన్) పంట', s: 'అవే వేర్ల నుంచి రెండో కోత', how: 'కోత తర్వాత చెరకు, అరటి వంటి పంటలు మోళ్ల నుంచి లేదా మొదలు నుంచి మళ్లీ పెరిగి, కొత్తగా నాటకుండానే మరో పంట ఇస్తాయి. నాటే ఖర్చు, సమయం ఆదా అవుతాయి; పాత మోళ్లను నేలకు దగ్గరగా సమానంగా కోసి, ఖాళీలు నింపి, సకాలంలో ఎరువు, నీరు ఇవ్వండి, అప్పుడు కార్శి పంట మంచి దిగుబడి ఇస్తుంది. పంట ఆరోగ్యంగా ఉన్నంత వరకే కార్శి తీసుకోండి.' },
  ta: { t: 'மறுதாம்பு (ரட்டூன்) பயிர்', s: 'அதே வேர்களிலிருந்து இரண்டாம் அறுவடை', how: 'அறுவடைக்குப் பின் கரும்பு, வாழை போன்ற பயிர்கள் அடிக்கட்டையிலிருந்து மீண்டும் வளர்ந்து, புதிதாக நடாமலே இன்னொரு பயிரைத் தரும். நடவுச் செலவும் நேரமும் மிச்சமாகும்; பழைய அடிக்கட்டைகளைத் தரையோடு சமமாக வெட்டி, இடைவெளிகளை நிரப்பி, சரியான நேரத்தில் உரமும் நீரும் கொடுத்தால் மறுதாம்பு நல்ல மகசூல் தரும். பயிர் ஆரோக்கியமாக இருக்கும் வரை மட்டுமே மறுதாம்பு விடுங்கள்.' } }
];
